INSERT IGNORE INTO graha_nakshatra (graha_id, nakshatra_id, interpretation_np, interpretation_en, positive_effects, challenges, career_indication, financial_indication, relationship_indication, classical_interpretation, sanskrit_reference, remedies) VALUES
(1,53,'सूर्य अश्विनी नक्षत्रमा रहँदा नेतृत्व शक्ति र नक्षत्र शक्ति मिसिन्छ — चिकित्सा र गतिको नक्षत्र। नक्षत्र स्वामी केतुसँग सूर्य तटस्थ हुनाले फल मध्यम रहन्छ। यो नक्षत्र मेष राशिको भागमा पर्ने हुनाले द्रुत उपचार शक्ति जस्ता फाइदा र जल्दबाजी जस्ता चुनौती दुवै देखिन्छ।',NULL,'द्रुत उपचार शक्ति, साहस, नयाँ सुरुवात, आत्मविश्वास, नेतृत्व','जल्दबाजी, अधुरो काम, अहंकार, क्रोध','चिकित्सा, खेलकुद, अनुसन्धान, प्रशासन','नयाँ स्रोतबाट छिटो लाभ, सरकारी स्रोतबाट लाभ, स्थिर आय','स्नेहमा तीव्रता, छिटो नजिक, आफ्नो कुरा मान्ने जिद','सूर्यो अश्विनी नक्षत्रे शुभाशुभं फलं ददाति।','Brihat Parashara Hora Shastra — Nakshatra Phala','रविवार सूर्यलाई जल अर्पण गर्ने।'),
(1,54,'सूर्य भरणी नक्षत्रमा रहँदा नेतृत्व शक्ति र नक्षत्र शक्ति मिसिन्छ — यमको नक्षत्र — भार बोक्ने र परिवर्तन। नक्षत्र स्वामी शुक्र सूर्यको शत्रु हुनाले चुनौती रहन्छ। यो नक्षत्र मेष राशिको भागमा पर्ने हुनाले सहनशीलता जस्ता फाइदा र दमन जस्ता चुनौती दुवै देखिन्छ।',NULL,'सहनशीलता, जिम्मेवारी, परिवर्तन साहस, आत्मविश्वास, नेतृत्व','दमन, अति बोझ, अहंकार, क्रोध','प्रशासन, सेवा, न्याय, राज्यसेवा','परिश्रमबाट स्थिर धन, सरकारी स्रोतबाट लाभ, स्थिर आय','वफादारी, तर दबाब, आफ्नो कुरा मान्ने जिद','सूर्यो भरणी नक्षत्रे शुभाशुभं फलं ददाति।','Brihat Parashara Hora Shastra — Nakshatra Phala','रविवार सूर्यलाई जल अर्पण गर्ने।'),
(1,55,'सूर्य कृत्तिका नक्षत्रमा रहँदा नेतृत्व शक्ति र नक्षत्र शक्ति मिसिन्छ — अग्निको नक्षत्र — शुद्धि र काट्ने शक्ति। नक्षत्र स्वामी स्वयं सूर्य भएकाले ग्रहको प्रभाव प्रबल हुन्छ। यो नक्षत्र मेष राशिको भागमा पर्ने हुनाले तीक्ष्ण बुद्धि जस्ता फाइदा र कटुवाणी जस्ता चुनौती दुवै देखिन्छ।',NULL,'तीक्ष्ण बुद्धि, शुद्धता, नेतृत्व, आत्मविश्वास, प्रतिष्ठा','कटुवाणी, जल्दी निर्णय, अहंकार, क्रोध','शिक्षण, चिकित्सा, अग्निसँग सम्बन्धित काम, प्रशासन','स्वाभिमानबाट आय, सरकारी स्रोतबाट लाभ, स्थिर आय','आदर चाहने, स्पष्टवादी, आफ्नो कुरा मान्ने जिद','सूर्यो कृत्तिका नक्षत्रे शुभाशुभं फलं ददाति।','Brihat Parashara Hora Shastra — Nakshatra Phala','रविवार सूर्यलाई जल अर्पण गर्ने।'),
(1,56,'सूर्य रोहिणी नक्षत्रमा रहँदा नेतृत्व शक्ति र नक्षत्र शक्ति मिसिन्छ — ब्रह्माको नक्षत्र — वृद्धि र सौन्दर्य। नक्षत्र स्वामी चन्द्र सूर्यको मित्रहुनाले फल सहज र शुभ हुन्छ। यो नक्षत्र वृषभ राशिको भागमा पर्ने हुनाले सृजनात्मकता जस्ता फाइदा र मोह जस्ता चुनौती दुवै देखिन्छ।',NULL,'सृजनात्मकता, सम्पत्ति वृद्धि, सौन्दर्य, आत्मविश्वास, नेतृत्व','मोह, अति आसक्ति, अहंकार, क्रोध','कला, कृषि, व्यवस्थापन, प्रशासन','सम्पत्ति र कृषिबाट लाभ, सरकारी स्रोतबाट लाभ, स्थिर आय','गहिरो स्नेह, सुन्दर सम्बन्ध, आफ्नो कुरा मान्ने जिद','सूर्यो रोहिणी नक्षत्रे शुभाशुभं फलं ददाति।','Brihat Parashara Hora Shastra — Nakshatra Phala','रविवार सूर्यलाई जल अर्पण गर्ने।'),
(1,57,'सूर्य मृगशिरा नक्षत्रमा रहँदा नेतृत्व शक्ति र नक्षत्र शक्ति मिसिन्छ — सोमको नक्षत्र — खोज र अन्वेषण। नक्षत्र स्वामी मङ्गल सूर्यको मित्रहुनाले फल सहज र शुभ हुन्छ। यो नक्षत्र वृषभ राशिको भागमा पर्ने हुनाले अन्वेषण जस्ता फाइदा र अस्थिर ध्यान जस्ता चुनौती दुवै देखिन्छ।',NULL,'अन्वेषण, जिज्ञासा, रचनात्मकता, आत्मविश्वास, नेतृत्व','अस्थिर ध्यान, भटकन, अहंकार, क्रोध','अनुसन्धान, यात्रा, डिजाइन, प्रशासन','खोजबाट लाभ, तर ढिलाइ, सरकारी स्रोतबाट लाभ','स्नेहमा खोज, अस्थिरता, आफ्नो कुरा मान्ने जिद','सूर्यो मृगशिरा नक्षत्रे शुभाशुभं फलं ददाति।','Brihat Parashara Hora Shastra — Nakshatra Phala','रविवार सूर्यलाई जल अर्पण गर्ने।'),
(1,58,'सूर्य आर्द्रा नक्षत्रमा रहँदा नेतृत्व शक्ति र नक्षत्र शक्ति मिसिन्छ — रुद्रको नक्षत्र — विनाश र पुनर्जन्म। नक्षत्र स्वामी मङ्गल सूर्यको मित्रहुनाले फल सहज र शुभ हुन्छ। यो नक्षत्र मिथुन राशिको भागमा पर्ने हुनाले संकटमा टिकाउपन जस्ता फाइदा र आवेग जस्ता चुनौती दुवै देखिन्छ।',NULL,'संकटमा टिकाउपन, तीक्ष्ण बुद्धि, परिवर्तन, आत्मविश्वास, नेतृत्व','आवेग, विवाद, तनाव, अहंकार','अनुसन्धान, चिकित्सा, सुरक्षा, प्रशासन','उतारचढाव, जोखिमबाट लाभ, सरकारी स्रोतबाट लाभ','तीव्र भावना, कहिलेकाहीं झगडा, आफ्नो कुरा मान्ने जिद','सूर्यो आर्द्रा नक्षत्रे शुभाशुभं फलं ददाति।','Brihat Parashara Hora Shastra — Nakshatra Phala','रविवार सूर्यलाई जल अर्पण गर्ने।'),
(1,59,'सूर्य पुनर्वसु नक्षत्रमा रहँदा नेतृत्व शक्ति र नक्षत्र शक्ति मिसिन्छ — आदितिको नक्षत्र — फिर्ता र नवीनीकरण। नक्षत्र स्वामी गुरु सूर्यको मित्रहुनाले फल सहज र शुभ हुन्छ। यो नक्षत्र मिथुन राशिको भागमा पर्ने हुनाले पुनर्स्थापना जस्ता फाइदा र ढिलाइ जस्ता चुनौती दुवै देखिन्छ।',NULL,'पुनर्स्थापना, भाग्य, सुरक्षा, आत्मविश्वास, नेतृत्व','ढिलाइ, पुरानो कुरामा फर्कने, अहंकार, क्रोध','शिक्षण, यात्रा, सेवा, प्रशासन','पुनः अवसरबाट लाभ, सरकारी स्रोतबाट लाभ, स्थिर आय','फेरि मिलाप, करुणा, आफ्नो कुरा मान्ने जिद','सूर्यो पुनर्वसु नक्षत्रे शुभाशुभं फलं ददाति।','Brihat Parashara Hora Shastra — Nakshatra Phala','रविवार सूर्यलाई जल अर्पण गर्ने।'),
(1,60,'सूर्य पुष्य नक्षत्रमा रहँदा नेतृत्व शक्ति र नक्षत्र शक्ति मिसिन्छ — बृहस्पतिको नक्षत्र — पोषण र शुभता। नक्षत्र स्वामी शनि सूर्यको शत्रु हुनाले चुनौती रहन्छ। यो नक्षत्र कर्क राशिको भागमा पर्ने हुनाले पोषण जस्ता फाइदा र अति निर्भरता जस्ता चुनौती दुवै देखिन्छ।',NULL,'पोषण, धर्म, सम्मान, शुभ आरम्भ, आत्मविश्वास','अति निर्भरता, दायित्व बढ्ने, अहंकार, क्रोध','शिक्षण, बैंकिङ, सेवा, कृषि','स्थिर र शुभ आय, सरकारी स्रोतबाट लाभ, स्थिर आय','स्नेहपूर्ण, परिवारमुखी, आफ्नो कुरा मान्ने जिद','सूर्यो पुष्य नक्षत्रे शुभाशुभं फलं ददाति।','Brihat Parashara Hora Shastra — Nakshatra Phala','रविवार सूर्यलाई जल अर्पण गर्ने।'),
(1,61,'सूर्य अश्लेषा नक्षत्रमा रहँदा नेतृत्व शक्ति र नक्षत्र शक्ति मिसिन्छ — नागको नक्षत्र — भ्रमण र रहस्य। नक्षत्र स्वामी बुध सूर्यको मित्रहुनाले फल सहज र शुभ हुन्छ। यो नक्षत्र कर्क राशिको भागमा पर्ने हुनाले अन्तर्दृष्टि जस्ता फाइदा र षड्यन्त्र जस्ता चुनौती दुवै देखिन्छ।',NULL,'अन्तर्दृष्टि, जादुई आकर्षण, गूढ ज्ञान, आत्मविश्वास, नेतृत्व','षड्यन्त्र, भ्रम, अति गोपन, अहंकार','अनुसन्धान, चिकित्सा, रहस्य विषय, प्रशासन','गोप्य स्रोतबाट लाभ, सरकारी स्रोतबाट लाभ, स्थिर आय','गहिरो आकर्षण, शंका, आफ्नो कुरा मान्ने जिद','सूर्यो अश्लेषा नक्षत्रे शुभाशुभं फलं ददाति।','Brihat Parashara Hora Shastra — Nakshatra Phala','रविवार सूर्यलाई जल अर्पण गर्ने।'),
(1,62,'सूर्य मघा नक्षत्रमा रहँदा नेतृत्व शक्ति र नक्षत्र शक्ति मिसिन्छ — पितृको नक्षत्र — राज्य र पूर्वज। नक्षत्र स्वामी केतुसँग सूर्य तटस्थ हुनाले फल मध्यम रहन्छ। यो नक्षत्र सिंह राशिको भागमा पर्ने हुनाले पूर्वजको आशीर्वाद जस्ता फाइदा र अहंकार जस्ता चुनौती दुवै देखिन्छ।',NULL,'पूर्वजको आशीर्वाद, नेतृत्व, प्रतिष्ठा, आत्मविश्वास, सरकारी सम्मान','अहंकार, परम्परामा जिद, क्रोध, जल्दबाजी','राजनीति, प्रशासन, पूर्वजसँग सम्बन्धित काम, राज्यसेवा','पारिवारिक सम्पत्ति, सरकारी स्रोतबाट लाभ, स्थिर आय','परिवार र सम्मानमा आधारित, आफ्नो कुरा मान्ने जिद, तर सम्मान','सूर्यो मघा नक्षत्रे शुभाशुभं फलं ददाति।','Brihat Parashara Hora Shastra — Nakshatra Phala','रविवार सूर्यलाई जल अर्पण गर्ने।'),
(1,63,'सूर्य पूर्व फल्गुनी नक्षत्रमा रहँदा नेतृत्व शक्ति र नक्षत्र शक्ति मिसिन्छ — भगको नक्षत्र — सुख र सृजना। नक्षत्र स्वामी शुक्र सूर्यको शत्रु हुनाले चुनौती रहन्छ। यो नक्षत्र सिंह राशिको भागमा पर्ने हुनाले कलात्मक सुख जस्ता फाइदा र अति सुख जस्ता चुनौती दुवै देखिन्छ।',NULL,'कलात्मक सुख, रोमान्स, वैभव, आत्मविश्वास, नेतृत्व','अति सुख, आलस्य, अहंकार, क्रोध','कला, मनोरञ्जन, सौन्दर्य, प्रशासन','सुख साधनबाट लाभ, सरकारी स्रोतबाट लाभ, स्थिर आय','प्रेमपूर्ण सम्बन्ध, आकर्षण, आफ्नो कुरा मान्ने जिद','सूर्यो पूर्व फल्गुनी नक्षत्रे शुभाशुभं फलं ददाति।','Brihat Parashara Hora Shastra — Nakshatra Phala','रविवार सूर्यलाई जल अर्पण गर्ने।'),
(1,64,'सूर्य उत्तरा फल्गुनी नक्षत्रमा रहँदा नेतृत्व शक्ति र नक्षत्र शक्ति मिसिन्छ — आर्यमाको नक्षत्र — सम्झौता र संरक्षण। नक्षत्र स्वामी स्वयं सूर्य भएकाले ग्रहको प्रभाव प्रबल हुन्छ। यो नक्षत्र सिंह राशिको भागमा पर्ने हुनाले साझेदारी जस्ता फाइदा र बाध्यता जस्ता चुनौती दुवै देखिन्छ।',NULL,'साझेदारी, संरक्षण, विश्वास, आत्मविश्वास, नेतृत्व','बाध्यता, अन्यमाथि निर्भरता, अहंकार, क्रोध','कानुन, साझेदारी, संस्था, प्रशासन','साझेदारीबाट लाभ, सरकारी स्रोतबाट लाभ, स्थिर आय','विश्वासयोग्य दीर्घ सम्बन्ध, आफ्नो कुरा मान्ने जिद, तर सम्मान','सूर्यो उत्तरा फल्गुनी नक्षत्रे शुभाशुभं फलं ददाति।','Brihat Parashara Hora Shastra — Nakshatra Phala','रविवार सूर्यलाई जल अर्पण गर्ने।'),
(1,65,'सूर्य हस्त नक्षत्रमा रहँदा नेतृत्व शक्ति र नक्षत्र शक्ति मिसिन्छ — सविताको नक्षत्र — हस्तकला र कौशल। नक्षत्र स्वामी चन्द्र सूर्यको मित्रहुनाले फल सहज र शुभ हुन्छ। यो नक्षत्र कन्या राशिको भागमा पर्ने हुनाले हस्तकला जस्ता फाइदा र चञ्चल हात जस्ता चुनौती दुवै देखिन्छ।',NULL,'हस्तकला, दक्षता, शीघ्र सिक्ने, आत्मविश्वास, नेतृत्व','चञ्चल हात, अधुरो काम, अहंकार, क्रोध','हस्तकला, चिकित्सा, डिजाइन, प्रशासन','सीपबाट आय, सरकारी स्रोतबाट लाभ, स्थिर आय','सेवामा आधारित स्नेह, आफ्नो कुरा मान्ने जिद, तर सम्मान','सूर्यो हस्त नक्षत्रे शुभाशुभं फलं ददाति।','Brihat Parashara Hora Shastra — Nakshatra Phala','रविवार सूर्यलाई जल अर्पण गर्ने।'),
(1,66,'सूर्य चित्रा नक्षत्रमा रहँदा नेतृत्व शक्ति र नक्षत्र शक्ति मिसिन्छ — विश्वकर्माको नक्षत्र — निर्माण र सजावट। नक्षत्र स्वामी मङ्गल सूर्यको मित्रहुनाले फल सहज र शुभ हुन्छ। यो नक्षत्र कन्या राशिको भागमा पर्ने हुनाले रचनात्मकता जस्ता फाइदा र दम्भ जस्ता चुनौती दुवै देखिन्छ।',NULL,'रचनात्मकता, सुन्दरता, प्रतिष्ठा, आत्मविश्वास, नेतृत्व','दम्भ, बाह्य सजावटमा ध्यान, अहंकार, क्रोध','वास्तुकला, डिजाइन, कला, प्रशासन','कलात्मक कामबाट लाभ, सरकारी स्रोतबाट लाभ, स्थिर आय','आकर्षण, तर गम्भीरता कम, आफ्नो कुरा मान्ने जिद','सूर्यो चित्रा नक्षत्रे शुभाशुभं फलं ददाति।','Brihat Parashara Hora Shastra — Nakshatra Phala','रविवार सूर्यलाई जल अर्पण गर्ने।'),
(1,67,'सूर्य स्वाति नक्षत्रमा रहँदा नेतृत्व शक्ति र नक्षत्र शक्ति मिसिन्छ — वायुको नक्षत्र — स्वतन्त्रता र व्यापार। नक्षत्र स्वामी राहुसँग सूर्य तटस्थ हुनाले फल मध्यम रहन्छ। यो नक्षत्र तुला राशिको भागमा पर्ने हुनाले स्वतन्त्रता जस्ता फाइदा र भटकन जस्ता चुनौती दुवै देखिन्छ।',NULL,'स्वतन्त्रता, व्यापारिक बुद्धि, सहनशीलता, आत्मविश्वास, नेतृत्व','भटकन, अस्थिरता, अहंकार, क्रोध','व्यापार, नीति, प्रविधि, प्रशासन','व्यापारबाट चल आय, सरकारी स्रोतबाट लाभ, स्थिर आय','स्वतन्त्रता चाहने सम्बन्ध, आफ्नो कुरा मान्ने जिद, तर सम्मान','सूर्यो स्वाति नक्षत्रे शुभाशुभं फलं ददाति।','Brihat Parashara Hora Shastra — Nakshatra Phala','रविवार सूर्यलाई जल अर्पण गर्ने।'),
(1,68,'सूर्य विशाखा नक्षत्रमा रहँदा नेतृत्व शक्ति र नक्षत्र शक्ति मिसिन्छ — इन्द्राग्निको नक्षत्र — लक्ष्य र उपलब्धि। नक्षत्र स्वामी गुरु सूर्यको मित्रहुनाले फल सहज र शुभ हुन्छ। यो नक्षत्र तुला राशिको भागमा पर्ने हुनाले लक्ष्य निश्चय जस्ता फाइदा र धैर्य कम जस्ता चुनौती दुवै देखिन्छ।',NULL,'लक्ष्य निश्चय, उपलब्धि, नेतृत्व, आत्मविश्वास, प्रतिष्ठा','धैर्य कम, अति महत्वाकांक्षा, अहंकार, क्रोध','व्यवस्थापन, इन्जिनियरिङ, नेतृत्व, प्रशासन','लक्ष्य पूर्तिबाट धन, सरकारी स्रोतबाट लाभ, स्थिर आय','लक्ष्यमुखी साझेदारी, आफ्नो कुरा मान्ने जिद, तर सम्मान','सूर्यो विशाखा नक्षत्रे शुभाशुभं फलं ददाति।','Brihat Parashara Hora Shastra — Nakshatra Phala','रविवार सूर्यलाई जल अर्पण गर्ने।'),
(1,69,'सूर्य अनुराधा नक्षत्रमा रहँदा नेतृत्व शक्ति र नक्षत्र शक्ति मिसिन्छ — मित्रको नक्षत्र — मित्रता र भक्ति। नक्षत्र स्वामी शनि सूर्यको शत्रु हुनाले चुनौती रहन्छ। यो नक्षत्र वृश्चिक राशिको भागमा पर्ने हुनाले मित्रता जस्ता फाइदा र मित्रमाथि अति अपेक्षा जस्ता चुनौती दुवै देखिन्छ।',NULL,'मित्रता, भक्ति, सङ्गठन क्षमता, आत्मविश्वास, नेतृत्व','मित्रमाथि अति अपेक्षा, अहंकार, क्रोध, जल्दबाजी','सङ्गठन, सेवा, धार्मिक कार्य, प्रशासन','मित्रबाट लाभ, सरकारी स्रोतबाट लाभ, स्थिर आय','गहिरो मित्रता, विश्वास, आफ्नो कुरा मान्ने जिद','सूर्यो अनुराधा नक्षत्रे शुभाशुभं फलं ददाति।','Brihat Parashara Hora Shastra — Nakshatra Phala','रविवार सूर्यलाई जल अर्पण गर्ने।'),
(1,70,'सूर्य ज्येष्ठा नक्षत्रमा रहँदा नेतृत्व शक्ति र नक्षत्र शक्ति मिसिन्छ — इन्द्रको नक्षत्र — वरिष्ठता र संरक्षण। नक्षत्र स्वामी बुध सूर्यको मित्रहुनाले फल सहज र शुभ हुन्छ। यो नक्षत्र वृश्चिक राशिको भागमा पर्ने हुनाले नेतृत्व जस्ता फाइदा र अहंकार जस्ता चुनौती दुवै देखिन्छ।',NULL,'नेतृत्व, संरक्षण, अनुभव, आत्मविश्वास, प्रतिष्ठा','अहंकार, ईर्ष्या, क्रोध, जल्दबाजी','प्रशासन, न्याय, वरिष्ठ पद, राज्यसेवा','स्थापित स्रोतबाट लाभ, सरकारी स्रोतबाट लाभ, स्थिर आय','संरक्षक भूमिका, आफ्नो कुरा मान्ने जिद, तर सम्मान','सूर्यो ज्येष्ठा नक्षत्रे शुभाशुभं फलं ददाति।','Brihat Parashara Hora Shastra — Nakshatra Phala','रविवार सूर्यलाई जल अर्पण गर्ने।'),
(1,71,'सूर्य मूल नक्षत्रमा रहँदा नेतृत्व शक्ति र नक्षत्र शक्ति मिसिन्छ — निर्तिको नक्षत्र — जरा र विनाश। नक्षत्र स्वामी केतुसँग सूर्य तटस्थ हुनाले फल मध्यम रहन्छ। यो नक्षत्र धनु राशिको भागमा पर्ने हुनाले जरा खोज्ने शक्ति जस्ता फाइदा र विनाशकारी प्रवृत्ति जस्ता चुनौती दुवै देखिन्छ।',NULL,'जरा खोज्ने शक्ति, परिवर्तन, पुनर्निर्माण, आत्मविश्वास, नेतृत्व','विनाशकारी प्रवृत्ति, आवेग, अहंकार, क्रोध','अनुसन्धान, चिकित्सा, क्रान्तिकारी काम, प्रशासन','उतारचढाव, पुनः सम्पत्ति, सरकारी स्रोतबाट लाभ','तीव्र, कहिलेकाहीं विच्छेद, आफ्नो कुरा मान्ने जिद','सूर्यो मूल नक्षत्रे शुभाशुभं फलं ददाति।','Brihat Parashara Hora Shastra — Nakshatra Phala','रविवार सूर्यलाई जल अर्पण गर्ने।'),
(1,72,'सूर्य पूर्वाषाढा नक्षत्रमा रहँदा नेतृत्व शक्ति र नक्षत्र शक्ति मिसिन्छ — अपस् नक्षत्र — अजेयता र प्रसार। नक्षत्र स्वामी शुक्र सूर्यको शत्रु हुनाले चुनौती रहन्छ। यो नक्षत्र धनु राशिको भागमा पर्ने हुनाले अजेय साहस जस्ता फाइदा र अति आत्मविश्वास जस्ता चुनौती दुवै देखिन्छ।',NULL,'अजेय साहस, प्रसार, विजय, आत्मविश्वास, नेतृत्व','अति आत्मविश्वास, टकराव, अहंकार, क्रोध','सेना, नीति, प्रसार, प्रशासन','विस्तारबाट लाभ, सरकारी स्रोतबाट लाभ, स्थिर आय','बलियो आवरण, तर दमन, आफ्नो कुरा मान्ने जिद','सूर्यो पूर्वाषाढा नक्षत्रे शुभाशुभं फलं ददाति।','Brihat Parashara Hora Shastra — Nakshatra Phala','रविवार सूर्यलाई जल अर्पण गर्ने।'),
(1,73,'सूर्य उत्तराषाढा नक्षत्रमा रहँदा नेतृत्व शक्ति र नक्षत्र शक्ति मिसिन्छ — विश्वदेवको नक्षत्र — अन्तिम विजय। नक्षत्र स्वामी स्वयं सूर्य भएकाले ग्रहको प्रभाव प्रबल हुन्छ। यो नक्षत्र धनु राशिको भागमा पर्ने हुनाले दिगो विजय जस्ता फाइदा र ढिलो फल जस्ता चुनौती दुवै देखिन्छ।',NULL,'दिगो विजय, सम्मान, धैर्यको फल, आत्मविश्वास, नेतृत्व','ढिलो फल, अन्तिम समयमा दबाब, अहंकार, क्रोध','प्रशासन, दीर्घ परियोजना, राज्यसेवा, नेतृत्व','दिगो र स्थिर सम्पत्ति, सरकारी स्रोतबाट लाभ, स्थिर आय','दीर्घकालीन, स्थिर, आफ्नो कुरा मान्ने जिद','सूर्यो उत्तराषाढा नक्षत्रे शुभाशुभं फलं ददाति।','Brihat Parashara Hora Shastra — Nakshatra Phala','रविवार सूर्यलाई जल अर्पण गर्ने।'),
(1,74,'सूर्य श्रवण नक्षत्रमा रहँदा नेतृत्व शक्ति र नक्षत्र शक्ति मिसिन्छ — विष्णुको नक्षत्र — सुन्ने र सिक्ने। नक्षत्र स्वामी चन्द्र सूर्यको मित्रहुनाले फल सहज र शुभ हुन्छ। यो नक्षत्र मकर राशिको भागमा पर्ने हुनाले ज्ञान जस्ता फाइदा र अति सुन्ने जस्ता चुनौती दुवै देखिन्छ।',NULL,'ज्ञान, श्रवण कला, सम्मान, आत्मविश्वास, नेतृत्व','अति सुन्ने, आलोचनामा संवेदनशील, अहंकार, क्रोध','शिक्षण, मीडिया, परामर्श, प्रशासन','ज्ञानबाट आय, सरकारी स्रोतबाट लाभ, स्थिर आय','कुरा सुन्ने सम्बन्ध, आफ्नो कुरा मान्ने जिद, तर सम्मान','सूर्यो श्रवण नक्षत्रे शुभाशुभं फलं ददाति।','Brihat Parashara Hora Shastra — Nakshatra Phala','रविवार सूर्यलाई जल अर्पण गर्ने।'),
(1,75,'सूर्य धनिष्ठा नक्षत्रमा रहँदा नेतृत्व शक्ति र नक्षत्र शक्ति मिसिन्छ — वसुको नक्षत्र — धन र समूह। नक्षत्र स्वामी मङ्गल सूर्यको मित्रहुनाले फल सहज र शुभ हुन्छ। यो नक्षत्र मकर राशिको भागमा पर्ने हुनाले धन संचय जस्ता फाइदा र समूहमा द्वन्द्व जस्ता चुनौती दुवै देखिन्छ।',NULL,'धन संचय, समूह नेतृत्व, कीर्ति, आत्मविश्वास, नेतृत्व','समूहमा द्वन्द्व, अहंकार, क्रोध, जल्दबाजी','व्यवस्थापन, समूह कार्य, संगीत, प्रशासन','समूह र धनबाट लाभ, सरकारी स्रोतबाट लाभ, स्थिर आय','सामूहिक कार्यमा मिलन, आफ्नो कुरा मान्ने जिद, तर सम्मान','सूर्यो धनिष्ठा नक्षत्रे शुभाशुभं फलं ददाति।','Brihat Parashara Hora Shastra — Nakshatra Phala','रविवार सूर्यलाई जल अर्पण गर्ने।'),
(1,76,'सूर्य शतभिषा नक्षत्रमा रहँदा नेतृत्व शक्ति र नक्षत्र शक्ति मिसिन्छ — वरुणको नक्षत्र — औषधि र रहस्य। नक्षत्र स्वामी राहुसँग सूर्य तटस्थ हुनाले फल मध्यम रहन्छ। यो नक्षत्र कुम्भ राशिको भागमा पर्ने हुनाले उपचार शक्ति जस्ता फाइदा र एकान्तवाद जस्ता चुनौती दुवै देखिन्छ।',NULL,'उपचार शक्ति, गूढ विज्ञान, एकान्त साधना, आत्मविश्वास, नेतृत्व','एकान्तवाद, भ्रम, अनिद्रा, अहंकार','चिकित्सा, विज्ञान, ज्योतिष, प्रशासन','अनियमित, गोप्य स्रोत, सरकारी स्रोतबाट लाभ','भावनात्मक दूरी, आफ्नो कुरा मान्ने जिद, तर सम्मान','सूर्यो शतभिषा नक्षत्रे शुभाशुभं फलं ददाति।','Brihat Parashara Hora Shastra — Nakshatra Phala','रविवार सूर्यलाई जल अर्पण गर्ने।'),
(1,77,'सूर्य पूर्व भाद्रपदा नक्षत्रमा रहँदा नेतृत्व शक्ति र नक्षत्र शक्ति मिसिन्छ — अज एकपदको नक्षत्र — तीव्र आदर्श। नक्षत्र स्वामी गुरु सूर्यको मित्रहुनाले फल सहज र शुभ हुन्छ। यो नक्षत्र कुम्भ राशिको भागमा पर्ने हुनाले दृढ आदर्श जस्ता फाइदा र तीव्रता जस्ता चुनौती दुवै देखिन्छ।',NULL,'दृढ आदर्श, त्याग, गहिरो चिन्तन, आत्मविश्वास, नेतृत्व','तीव्रता, अन्यमाथि दबाब, अहंकार, क्रोध','आध्यात्मिक कार्य, अनुसन्धान, प्रशासन, राज्यसेवा','आदर्शका लागि त्याग, सरकारी स्रोतबाट लाभ, स्थिर आय','भावनात्मक तीव्रता, आफ्नो कुरा मान्ने जिद, तर सम्मान','सूर्यो पूर्व भाद्रपदा नक्षत्रे शुभाशुभं फलं ददाति।','Brihat Parashara Hora Shastra — Nakshatra Phala','रविवार सूर्यलाई जल अर्पण गर्ने।'),
(1,78,'सूर्य उत्तर भाद्रपदा नक्षत्रमा रहँदा नेतृत्व शक्ति र नक्षत्र शक्ति मिसिन्छ — अहिर्बुध्न्यको नक्षत्र — गहिरो ज्ञान। नक्षत्र स्वामी शनि सूर्यको शत्रु हुनाले चुनौती रहन्छ। यो नक्षत्र मीन राशिको भागमा पर्ने हुनाले धैर्य जस्ता फाइदा र गम्भीरतामा अति जस्ता चुनौती दुवै देखिन्छ।',NULL,'धैर्य, गहिरो ज्ञान, दीर्घ आयु, आत्मविश्वास, नेतृत्व','गम्भीरतामा अति, मौनता, अहंकार, क्रोध','विद्या, अनुसन्धान, परामर्श, प्रशासन','दीर्घकालीन बचत, सरकारी स्रोतबाट लाभ, स्थिर आय','गम्भीर र दिगो सम्बन्ध, आफ्नो कुरा मान्ने जिद, तर सम्मान','सूर्यो उत्तर भाद्रपदा नक्षत्रे शुभाशुभं फलं ददाति।','Brihat Parashara Hora Shastra — Nakshatra Phala','रविवार सूर्यलाई जल अर्पण गर्ने।'),
(1,79,'सूर्य रेवती नक्षत्रमा रहँदा नेतृत्व शक्ति र नक्षत्र शक्ति मिसिन्छ — पुषणको नक्षत्र — पूर्णता र पोषण। नक्षत्र स्वामी बुध सूर्यको मित्रहुनाले फल सहज र शुभ हुन्छ। यो नक्षत्र मीन राशिको भागमा पर्ने हुनाले पूर्णता जस्ता फाइदा र अन्त्यमा ढिलाइ जस्ता चुनौती दुवै देखिन्छ।',NULL,'पूर्णता, सुरक्षित यात्रा, पोषण, आत्मविश्वास, नेतृत्व','अन्त्यमा ढिलाइ, अति संरक्षण, अहंकार, क्रोध','यात्रा, सेवा, परिवहन, प्रशासन','सुरक्षित, तर सानो, सरकारी स्रोतबाट लाभ','पोषक सम्बन्ध, ममता, आफ्नो कुरा मान्ने जिद','सूर्यो रेवती नक्षत्रे शुभाशुभं फलं ददाति।','Brihat Parashara Hora Shastra — Nakshatra Phala','रविवार सूर्यलाई जल अर्पण गर्ने।'),
(2,53,'चन्द्र अश्विनी नक्षत्रमा रहँदा भावनात्मक प्रभाव र नक्षत्र शक्ति मिसिन्छ — चिकित्सा र गतिको नक्षत्र। नक्षत्र स्वामी केतुसँग चन्द्र तटस्थ हुनाले फल मध्यम रहन्छ। यो नक्षत्र मेष राशिको भागमा पर्ने हुनाले द्रुत उपचार शक्ति जस्ता फाइदा र जल्दबाजी जस्ता चुनौती दुवै देखिन्छ।',NULL,'द्रुत उपचार शक्ति, साहस, नयाँ सुरुवात, लोकप्रियता, करुणा','जल्दबाजी, अधुरो काम, मनोद्वन्द्व, भावनात्मक अस्थिरता','चिकित्सा, खेलकुद, अनुसन्धान, जनसेवा','नयाँ स्रोतबाट छिटो लाभ, चल सम्पत्ति, जलजन्य आय','स्नेहमा तीव्रता, छिटो नजिक, गहिरो स्नेह','चन्द्रो अश्विनी नक्षत्रे शुभाशुभं फलं ददाति।','Brihat Parashara Hora Shastra — Nakshatra Phala','सोमबार शिवलिंगमा जल चढाउने।'),
(2,54,'चन्द्र भरणी नक्षत्रमा रहँदा भावनात्मक प्रभाव र नक्षत्र शक्ति मिसिन्छ — यमको नक्षत्र — भार बोक्ने र परिवर्तन। नक्षत्र स्वामी शुक्र चन्द्रको शत्रु हुनाले चुनौती रहन्छ। यो नक्षत्र मेष राशिको भागमा पर्ने हुनाले सहनशीलता जस्ता फाइदा र दमन जस्ता चुनौती दुवै देखिन्छ।',NULL,'सहनशीलता, जिम्मेवारी, परिवर्तन साहस, लोकप्रियता, करुणा','दमन, अति बोझ, मनोद्वन्द्व, भावनात्मक अस्थिरता','प्रशासन, सेवा, न्याय, जनसेवा','परिश्रमबाट स्थिर धन, चल सम्पत्ति, जलजन्य आय','वफादारी, तर दबाब, गहिरो स्नेह','चन्द्रो भरणी नक्षत्रे शुभाशुभं फलं ददाति।','Brihat Parashara Hora Shastra — Nakshatra Phala','सोमबार शिवलिंगमा जल चढाउने।'),
(2,55,'चन्द्र कृत्तिका नक्षत्रमा रहँदा भावनात्मक प्रभाव र नक्षत्र शक्ति मिसिन्छ — अग्निको नक्षत्र — शुद्धि र काट्ने शक्ति। नक्षत्र स्वामी सूर्य चन्द्रको मित्रहुनाले फल सहज र शुभ हुन्छ। यो नक्षत्र मेष राशिको भागमा पर्ने हुनाले तीक्ष्ण बुद्धि जस्ता फाइदा र कटुवाणी जस्ता चुनौती दुवै देखिन्छ।',NULL,'तीक्ष्ण बुद्धि, शुद्धता, नेतृत्व, लोकप्रियता, करुणा','कटुवाणी, जल्दी निर्णय, मनोद्वन्द्व, भावनात्मक अस्थिरता','शिक्षण, चिकित्सा, अग्निसँग सम्बन्धित काम, जनसेवा','स्वाभिमानबाट आय, चल सम्पत्ति, जलजन्य आय','आदर चाहने, स्पष्टवादी, गहिरो स्नेह','चन्द्रो कृत्तिका नक्षत्रे शुभाशुभं फलं ददाति।','Brihat Parashara Hora Shastra — Nakshatra Phala','सोमबार शिवलिंगमा जल चढाउने।'),
(2,56,'चन्द्र रोहिणी नक्षत्रमा रहँदा भावनात्मक प्रभाव र नक्षत्र शक्ति मिसिन्छ — ब्रह्माको नक्षत्र — वृद्धि र सौन्दर्य। नक्षत्र स्वामी स्वयं चन्द्र भएकाले ग्रहको प्रभाव प्रबल हुन्छ। यो नक्षत्र वृषभ राशिको भागमा पर्ने हुनाले सृजनात्मकता जस्ता फाइदा र मोह जस्ता चुनौती दुवै देखिन्छ।',NULL,'सृजनात्मकता, सम्पत्ति वृद्धि, सौन्दर्य, लोकप्रियता, करुणा','मोह, अति आसक्ति, मनोद्वन्द्व, भावनात्मक अस्थिरता','कला, कृषि, व्यवस्थापन, जनसेवा','सम्पत्ति र कृषिबाट लाभ, चल सम्पत्ति, जलजन्य आय','गहिरो स्नेह, सुन्दर सम्बन्ध, भावनामा उतारचढाव','चन्द्रो रोहिणी नक्षत्रे शुभाशुभं फलं ददाति।','Brihat Parashara Hora Shastra — Nakshatra Phala','सोमबार शिवलिंगमा जल चढाउने।'),
(2,57,'चन्द्र मृगशिरा नक्षत्रमा रहँदा भावनात्मक प्रभाव र नक्षत्र शक्ति मिसिन्छ — सोमको नक्षत्र — खोज र अन्वेषण। नक्षत्र स्वामी मङ्गल चन्द्रको मित्रहुनाले फल सहज र शुभ हुन्छ। यो नक्षत्र वृषभ राशिको भागमा पर्ने हुनाले अन्वेषण जस्ता फाइदा र अस्थिर ध्यान जस्ता चुनौती दुवै देखिन्छ।',NULL,'अन्वेषण, जिज्ञासा, रचनात्मकता, लोकप्रियता, करुणा','अस्थिर ध्यान, भटकन, मनोद्वन्द्व, भावनात्मक अस्थिरता','अनुसन्धान, यात्रा, डिजाइन, जनसेवा','खोजबाट लाभ, तर ढिलाइ, चल सम्पत्ति','स्नेहमा खोज, अस्थिरता, गहिरो स्नेह','चन्द्रो मृगशिरा नक्षत्रे शुभाशुभं फलं ददाति।','Brihat Parashara Hora Shastra — Nakshatra Phala','सोमबार शिवलिंगमा जल चढाउने।'),
(2,58,'चन्द्र आर्द्रा नक्षत्रमा रहँदा भावनात्मक प्रभाव र नक्षत्र शक्ति मिसिन्छ — रुद्रको नक्षत्र — विनाश र पुनर्जन्म। नक्षत्र स्वामी मङ्गल चन्द्रको मित्रहुनाले फल सहज र शुभ हुन्छ। यो नक्षत्र मिथुन राशिको भागमा पर्ने हुनाले संकटमा टिकाउपन जस्ता फाइदा र आवेग जस्ता चुनौती दुवै देखिन्छ।',NULL,'संकटमा टिकाउपन, तीक्ष्ण बुद्धि, परिवर्तन, लोकप्रियता, करुणा','आवेग, विवाद, तनाव, मनोद्वन्द्व','अनुसन्धान, चिकित्सा, सुरक्षा, जनसेवा','उतारचढाव, जोखिमबाट लाभ, चल सम्पत्ति','तीव्र भावना, कहिलेकाहीं झगडा, गहिरो स्नेह','चन्द्रो आर्द्रा नक्षत्रे शुभाशुभं फलं ददाति।','Brihat Parashara Hora Shastra — Nakshatra Phala','सोमबार शिवलिंगमा जल चढाउने।'),
(2,59,'चन्द्र पुनर्वसु नक्षत्रमा रहँदा भावनात्मक प्रभाव र नक्षत्र शक्ति मिसिन्छ — आदितिको नक्षत्र — फिर्ता र नवीनीकरण। नक्षत्र स्वामी गुरु चन्द्रको मित्रहुनाले फल सहज र शुभ हुन्छ। यो नक्षत्र मिथुन राशिको भागमा पर्ने हुनाले पुनर्स्थापना जस्ता फाइदा र ढिलाइ जस्ता चुनौती दुवै देखिन्छ।',NULL,'पुनर्स्थापना, भाग्य, सुरक्षा, लोकप्रियता, करुणा','ढिलाइ, पुरानो कुरामा फर्कने, मनोद्वन्द्व, भावनात्मक अस्थिरता','शिक्षण, यात्रा, सेवा, जनसेवा','पुनः अवसरबाट लाभ, चल सम्पत्ति, जलजन्य आय','फेरि मिलाप, करुणा, गहिरो स्नेह','चन्द्रो पुनर्वसु नक्षत्रे शुभाशुभं फलं ददाति।','Brihat Parashara Hora Shastra — Nakshatra Phala','सोमबार शिवलिंगमा जल चढाउने।'),
(2,60,'चन्द्र पुष्य नक्षत्रमा रहँदा भावनात्मक प्रभाव र नक्षत्र शक्ति मिसिन्छ — बृहस्पतिको नक्षत्र — पोषण र शुभता। नक्षत्र स्वामी शनि चन्द्रको शत्रु हुनाले चुनौती रहन्छ। यो नक्षत्र कर्क राशिको भागमा पर्ने हुनाले पोषण जस्ता फाइदा र अति निर्भरता जस्ता चुनौती दुवै देखिन्छ।',NULL,'पोषण, धर्म, सम्मान, शुभ आरम्भ, लोकप्रियता','अति निर्भरता, दायित्व बढ्ने, मनोद्वन्द्व, भावनात्मक अस्थिरता','शिक्षण, बैंकिङ, सेवा, कृषि','स्थिर र शुभ आय, चल सम्पत्ति, जलजन्य आय','स्नेहपूर्ण, परिवारमुखी, गहिरो स्नेह','चन्द्रो पुष्य नक्षत्रे शुभाशुभं फलं ददाति।','Brihat Parashara Hora Shastra — Nakshatra Phala','सोमबार शिवलिंगमा जल चढाउने।'),
(2,61,'चन्द्र अश्लेषा नक्षत्रमा रहँदा भावनात्मक प्रभाव र नक्षत्र शक्ति मिसिन्छ — नागको नक्षत्र — भ्रमण र रहस्य। नक्षत्र स्वामी बुध चन्द्रको शत्रु हुनाले चुनौती रहन्छ। यो नक्षत्र कर्क राशिको भागमा पर्ने हुनाले अन्तर्दृष्टि जस्ता फाइदा र षड्यन्त्र जस्ता चुनौती दुवै देखिन्छ।',NULL,'अन्तर्दृष्टि, जादुई आकर्षण, गूढ ज्ञान, लोकप्रियता, करुणा','षड्यन्त्र, भ्रम, अति गोपन, मनोद्वन्द्व','अनुसन्धान, चिकित्सा, रहस्य विषय, जनसेवा','गोप्य स्रोतबाट लाभ, चल सम्पत्ति, जलजन्य आय','गहिरो आकर्षण, शंका, गहिरो स्नेह','चन्द्रो अश्लेषा नक्षत्रे शुभाशुभं फलं ददाति।','Brihat Parashara Hora Shastra — Nakshatra Phala','सोमबार शिवलिंगमा जल चढाउने।'),
(2,62,'चन्द्र मघा नक्षत्रमा रहँदा भावनात्मक प्रभाव र नक्षत्र शक्ति मिसिन्छ — पितृको नक्षत्र — राज्य र पूर्वज। नक्षत्र स्वामी केतुसँग चन्द्र तटस्थ हुनाले फल मध्यम रहन्छ। यो नक्षत्र सिंह राशिको भागमा पर्ने हुनाले पूर्वजको आशीर्वाद जस्ता फाइदा र अहंकार जस्ता चुनौती दुवै देखिन्छ।',NULL,'पूर्वजको आशीर्वाद, नेतृत्व, प्रतिष्ठा, लोकप्रियता, करुणा','अहंकार, परम्परामा जिद, मनोद्वन्द्व, भावनात्मक अस्थिरता','राजनीति, प्रशासन, पूर्वजसँग सम्बन्धित काम, जनसेवा','पारिवारिक सम्पत्ति, चल सम्पत्ति, जलजन्य आय','परिवार र सम्मानमा आधारित, गहिरो स्नेह, भावनामा उतारचढाव','चन्द्रो मघा नक्षत्रे शुभाशुभं फलं ददाति।','Brihat Parashara Hora Shastra — Nakshatra Phala','सोमबार शिवलिंगमा जल चढाउने।'),
(2,63,'चन्द्र पूर्व फल्गुनी नक्षत्रमा रहँदा भावनात्मक प्रभाव र नक्षत्र शक्ति मिसिन्छ — भगको नक्षत्र — सुख र सृजना। नक्षत्र स्वामी शुक्र चन्द्रको शत्रु हुनाले चुनौती रहन्छ। यो नक्षत्र सिंह राशिको भागमा पर्ने हुनाले कलात्मक सुख जस्ता फाइदा र अति सुख जस्ता चुनौती दुवै देखिन्छ।',NULL,'कलात्मक सुख, रोमान्स, वैभव, लोकप्रियता, करुणा','अति सुख, आलस्य, मनोद्वन्द्व, भावनात्मक अस्थिरता','कला, मनोरञ्जन, सौन्दर्य, जनसेवा','सुख साधनबाट लाभ, चल सम्पत्ति, जलजन्य आय','प्रेमपूर्ण सम्बन्ध, आकर्षण, गहिरो स्नेह','चन्द्रो पूर्व फल्गुनी नक्षत्रे शुभाशुभं फलं ददाति।','Brihat Parashara Hora Shastra — Nakshatra Phala','सोमबार शिवलिंगमा जल चढाउने।'),
(2,64,'चन्द्र उत्तरा फल्गुनी नक्षत्रमा रहँदा भावनात्मक प्रभाव र नक्षत्र शक्ति मिसिन्छ — आर्यमाको नक्षत्र — सम्झौता र संरक्षण। नक्षत्र स्वामी सूर्य चन्द्रको मित्रहुनाले फल सहज र शुभ हुन्छ। यो नक्षत्र सिंह राशिको भागमा पर्ने हुनाले साझेदारी जस्ता फाइदा र बाध्यता जस्ता चुनौती दुवै देखिन्छ।',NULL,'साझेदारी, संरक्षण, विश्वास, लोकप्रियता, करुणा','बाध्यता, अन्यमाथि निर्भरता, मनोद्वन्द्व, भावनात्मक अस्थिरता','कानुन, साझेदारी, संस्था, जनसेवा','साझेदारीबाट लाभ, चल सम्पत्ति, जलजन्य आय','विश्वासयोग्य दीर्घ सम्बन्ध, गहिरो स्नेह, भावनामा उतारचढाव','चन्द्रो उत्तरा फल्गुनी नक्षत्रे शुभाशुभं फलं ददाति।','Brihat Parashara Hora Shastra — Nakshatra Phala','सोमबार शिवलिंगमा जल चढाउने।'),
(2,65,'चन्द्र हस्त नक्षत्रमा रहँदा भावनात्मक प्रभाव र नक्षत्र शक्ति मिसिन्छ — सविताको नक्षत्र — हस्तकला र कौशल। नक्षत्र स्वामी स्वयं चन्द्र भएकाले ग्रहको प्रभाव प्रबल हुन्छ। यो नक्षत्र कन्या राशिको भागमा पर्ने हुनाले हस्तकला जस्ता फाइदा र चञ्चल हात जस्ता चुनौती दुवै देखिन्छ।',NULL,'हस्तकला, दक्षता, शीघ्र सिक्ने, लोकप्रियता, करुणा','चञ्चल हात, अधुरो काम, मनोद्वन्द्व, भावनात्मक अस्थिरता','हस्तकला, चिकित्सा, डिजाइन, जनसेवा','सीपबाट आय, चल सम्पत्ति, जलजन्य आय','सेवामा आधारित स्नेह, गहिरो स्नेह, भावनामा उतारचढाव','चन्द्रो हस्त नक्षत्रे शुभाशुभं फलं ददाति।','Brihat Parashara Hora Shastra — Nakshatra Phala','सोमबार शिवलिंगमा जल चढाउने।'),
(2,66,'चन्द्र चित्रा नक्षत्रमा रहँदा भावनात्मक प्रभाव र नक्षत्र शक्ति मिसिन्छ — विश्वकर्माको नक्षत्र — निर्माण र सजावट। नक्षत्र स्वामी मङ्गल चन्द्रको मित्रहुनाले फल सहज र शुभ हुन्छ। यो नक्षत्र कन्या राशिको भागमा पर्ने हुनाले रचनात्मकता जस्ता फाइदा र दम्भ जस्ता चुनौती दुवै देखिन्छ।',NULL,'रचनात्मकता, सुन्दरता, प्रतिष्ठा, लोकप्रियता, करुणा','दम्भ, बाह्य सजावटमा ध्यान, मनोद्वन्द्व, भावनात्मक अस्थिरता','वास्तुकला, डिजाइन, कला, जनसेवा','कलात्मक कामबाट लाभ, चल सम्पत्ति, जलजन्य आय','आकर्षण, तर गम्भीरता कम, गहिरो स्नेह','चन्द्रो चित्रा नक्षत्रे शुभाशुभं फलं ददाति।','Brihat Parashara Hora Shastra — Nakshatra Phala','सोमबार शिवलिंगमा जल चढाउने।'),
(2,67,'चन्द्र स्वाति नक्षत्रमा रहँदा भावनात्मक प्रभाव र नक्षत्र शक्ति मिसिन्छ — वायुको नक्षत्र — स्वतन्त्रता र व्यापार। नक्षत्र स्वामी राहुसँग चन्द्र तटस्थ हुनाले फल मध्यम रहन्छ। यो नक्षत्र तुला राशिको भागमा पर्ने हुनाले स्वतन्त्रता जस्ता फाइदा र भटकन जस्ता चुनौती दुवै देखिन्छ।',NULL,'स्वतन्त्रता, व्यापारिक बुद्धि, सहनशीलता, लोकप्रियता, करुणा','भटकन, अस्थिरता, मनोद्वन्द्व, भावनात्मक अस्थिरता','व्यापार, नीति, प्रविधि, जनसेवा','व्यापारबाट चल आय, चल सम्पत्ति, जलजन्य आय','स्वतन्त्रता चाहने सम्बन्ध, गहिरो स्नेह, भावनामा उतारचढाव','चन्द्रो स्वाति नक्षत्रे शुभाशुभं फलं ददाति।','Brihat Parashara Hora Shastra — Nakshatra Phala','सोमबार शिवलिंगमा जल चढाउने।'),
(2,68,'चन्द्र विशाखा नक्षत्रमा रहँदा भावनात्मक प्रभाव र नक्षत्र शक्ति मिसिन्छ — इन्द्राग्निको नक्षत्र — लक्ष्य र उपलब्धि। नक्षत्र स्वामी गुरु चन्द्रको मित्रहुनाले फल सहज र शुभ हुन्छ। यो नक्षत्र तुला राशिको भागमा पर्ने हुनाले लक्ष्य निश्चय जस्ता फाइदा र धैर्य कम जस्ता चुनौती दुवै देखिन्छ।',NULL,'लक्ष्य निश्चय, उपलब्धि, नेतृत्व, लोकप्रियता, करुणा','धैर्य कम, अति महत्वाकांक्षा, मनोद्वन्द्व, भावनात्मक अस्थिरता','व्यवस्थापन, इन्जिनियरिङ, नेतृत्व, जनसेवा','लक्ष्य पूर्तिबाट धन, चल सम्पत्ति, जलजन्य आय','लक्ष्यमुखी साझेदारी, गहिरो स्नेह, भावनामा उतारचढाव','चन्द्रो विशाखा नक्षत्रे शुभाशुभं फलं ददाति।','Brihat Parashara Hora Shastra — Nakshatra Phala','सोमबार शिवलिंगमा जल चढाउने।'),
(2,69,'चन्द्र अनुराधा नक्षत्रमा रहँदा भावनात्मक प्रभाव र नक्षत्र शक्ति मिसिन्छ — मित्रको नक्षत्र — मित्रता र भक्ति। नक्षत्र स्वामी शनि चन्द्रको शत्रु हुनाले चुनौती रहन्छ। यो नक्षत्र वृश्चिक राशिको भागमा पर्ने हुनाले मित्रता जस्ता फाइदा र मित्रमाथि अति अपेक्षा जस्ता चुनौती दुवै देखिन्छ।',NULL,'मित्रता, भक्ति, सङ्गठन क्षमता, लोकप्रियता, करुणा','मित्रमाथि अति अपेक्षा, मनोद्वन्द्व, भावनात्मक अस्थिरता','सङ्गठन, सेवा, धार्मिक कार्य, जनसेवा','मित्रबाट लाभ, चल सम्पत्ति, जलजन्य आय','गहिरो मित्रता, विश्वास, गहिरो स्नेह','चन्द्रो अनुराधा नक्षत्रे शुभाशुभं फलं ददाति।','Brihat Parashara Hora Shastra — Nakshatra Phala','सोमबार शिवलिंगमा जल चढाउने।'),
(2,70,'चन्द्र ज्येष्ठा नक्षत्रमा रहँदा भावनात्मक प्रभाव र नक्षत्र शक्ति मिसिन्छ — इन्द्रको नक्षत्र — वरिष्ठता र संरक्षण। नक्षत्र स्वामी बुध चन्द्रको शत्रु हुनाले चुनौती रहन्छ। यो नक्षत्र वृश्चिक राशिको भागमा पर्ने हुनाले नेतृत्व जस्ता फाइदा र अहंकार जस्ता चुनौती दुवै देखिन्छ।',NULL,'नेतृत्व, संरक्षण, अनुभव, लोकप्रियता, करुणा','अहंकार, ईर्ष्या, मनोद्वन्द्व, भावनात्मक अस्थिरता','प्रशासन, न्याय, वरिष्ठ पद, जनसेवा','स्थापित स्रोतबाट लाभ, चल सम्पत्ति, जलजन्य आय','संरक्षक भूमिका, गहिरो स्नेह, भावनामा उतारचढाव','चन्द्रो ज्येष्ठा नक्षत्रे शुभाशुभं फलं ददाति।','Brihat Parashara Hora Shastra — Nakshatra Phala','सोमबार शिवलिंगमा जल चढाउने।'),
(2,71,'चन्द्र मूल नक्षत्रमा रहँदा भावनात्मक प्रभाव र नक्षत्र शक्ति मिसिन्छ — निर्तिको नक्षत्र — जरा र विनाश। नक्षत्र स्वामी केतुसँग चन्द्र तटस्थ हुनाले फल मध्यम रहन्छ। यो नक्षत्र धनु राशिको भागमा पर्ने हुनाले जरा खोज्ने शक्ति जस्ता फाइदा र विनाशकारी प्रवृत्ति जस्ता चुनौती दुवै देखिन्छ।',NULL,'जरा खोज्ने शक्ति, परिवर्तन, पुनर्निर्माण, लोकप्रियता, करुणा','विनाशकारी प्रवृत्ति, आवेग, मनोद्वन्द्व, भावनात्मक अस्थिरता','अनुसन्धान, चिकित्सा, क्रान्तिकारी काम, जनसेवा','उतारचढाव, पुनः सम्पत्ति, चल सम्पत्ति','तीव्र, कहिलेकाहीं विच्छेद, गहिरो स्नेह','चन्द्रो मूल नक्षत्रे शुभाशुभं फलं ददाति।','Brihat Parashara Hora Shastra — Nakshatra Phala','सोमबार शिवलिंगमा जल चढाउने।'),
(2,72,'चन्द्र पूर्वाषाढा नक्षत्रमा रहँदा भावनात्मक प्रभाव र नक्षत्र शक्ति मिसिन्छ — अपस् नक्षत्र — अजेयता र प्रसार। नक्षत्र स्वामी शुक्र चन्द्रको शत्रु हुनाले चुनौती रहन्छ। यो नक्षत्र धनु राशिको भागमा पर्ने हुनाले अजेय साहस जस्ता फाइदा र अति आत्मविश्वास जस्ता चुनौती दुवै देखिन्छ।',NULL,'अजेय साहस, प्रसार, विजय, लोकप्रियता, करुणा','अति आत्मविश्वास, टकराव, मनोद्वन्द्व, भावनात्मक अस्थिरता','सेना, नीति, प्रसार, जनसेवा','विस्तारबाट लाभ, चल सम्पत्ति, जलजन्य आय','बलियो आवरण, तर दमन, गहिरो स्नेह','चन्द्रो पूर्वाषाढा नक्षत्रे शुभाशुभं फलं ददाति।','Brihat Parashara Hora Shastra — Nakshatra Phala','सोमबार शिवलिंगमा जल चढाउने।'),
(2,73,'चन्द्र उत्तराषाढा नक्षत्रमा रहँदा भावनात्मक प्रभाव र नक्षत्र शक्ति मिसिन्छ — विश्वदेवको नक्षत्र — अन्तिम विजय। नक्षत्र स्वामी सूर्य चन्द्रको मित्रहुनाले फल सहज र शुभ हुन्छ। यो नक्षत्र धनु राशिको भागमा पर्ने हुनाले दिगो विजय जस्ता फाइदा र ढिलो फल जस्ता चुनौती दुवै देखिन्छ।',NULL,'दिगो विजय, सम्मान, धैर्यको फल, लोकप्रियता, करुणा','ढिलो फल, अन्तिम समयमा दबाब, मनोद्वन्द्व, भावनात्मक अस्थिरता','प्रशासन, दीर्घ परियोजना, जनसेवा, शिक्षा','दिगो र स्थिर सम्पत्ति, चल सम्पत्ति, जलजन्य आय','दीर्घकालीन, स्थिर, गहिरो स्नेह','चन्द्रो उत्तराषाढा नक्षत्रे शुभाशुभं फलं ददाति।','Brihat Parashara Hora Shastra — Nakshatra Phala','सोमबार शिवलिंगमा जल चढाउने।'),
(2,74,'चन्द्र श्रवण नक्षत्रमा रहँदा भावनात्मक प्रभाव र नक्षत्र शक्ति मिसिन्छ — विष्णुको नक्षत्र — सुन्ने र सिक्ने। नक्षत्र स्वामी स्वयं चन्द्र भएकाले ग्रहको प्रभाव प्रबल हुन्छ। यो नक्षत्र मकर राशिको भागमा पर्ने हुनाले ज्ञान जस्ता फाइदा र अति सुन्ने जस्ता चुनौती दुवै देखिन्छ।',NULL,'ज्ञान, श्रवण कला, सम्मान, लोकप्रियता, करुणा','अति सुन्ने, आलोचनामा संवेदनशील, मनोद्वन्द्व, भावनात्मक अस्थिरता','शिक्षण, मीडिया, परामर्श, जनसेवा','ज्ञानबाट आय, चल सम्पत्ति, जलजन्य आय','कुरा सुन्ने सम्बन्ध, गहिरो स्नेह, भावनामा उतारचढाव','चन्द्रो श्रवण नक्षत्रे शुभाशुभं फलं ददाति।','Brihat Parashara Hora Shastra — Nakshatra Phala','सोमबार शिवलिंगमा जल चढाउने।'),
(2,75,'चन्द्र धनिष्ठा नक्षत्रमा रहँदा भावनात्मक प्रभाव र नक्षत्र शक्ति मिसिन्छ — वसुको नक्षत्र — धन र समूह। नक्षत्र स्वामी मङ्गल चन्द्रको मित्रहुनाले फल सहज र शुभ हुन्छ। यो नक्षत्र मकर राशिको भागमा पर्ने हुनाले धन संचय जस्ता फाइदा र समूहमा द्वन्द्व जस्ता चुनौती दुवै देखिन्छ।',NULL,'धन संचय, समूह नेतृत्व, कीर्ति, लोकप्रियता, करुणा','समूहमा द्वन्द्व, अहंकार, मनोद्वन्द्व, भावनात्मक अस्थिरता','व्यवस्थापन, समूह कार्य, संगीत, जनसेवा','समूह र धनबाट लाभ, चल सम्पत्ति, जलजन्य आय','सामूहिक कार्यमा मिलन, गहिरो स्नेह, भावनामा उतारचढाव','चन्द्रो धनिष्ठा नक्षत्रे शुभाशुभं फलं ददाति।','Brihat Parashara Hora Shastra — Nakshatra Phala','सोमबार शिवलिंगमा जल चढाउने।'),
(2,76,'चन्द्र शतभिषा नक्षत्रमा रहँदा भावनात्मक प्रभाव र नक्षत्र शक्ति मिसिन्छ — वरुणको नक्षत्र — औषधि र रहस्य। नक्षत्र स्वामी राहुसँग चन्द्र तटस्थ हुनाले फल मध्यम रहन्छ। यो नक्षत्र कुम्भ राशिको भागमा पर्ने हुनाले उपचार शक्ति जस्ता फाइदा र एकान्तवाद जस्ता चुनौती दुवै देखिन्छ।',NULL,'उपचार शक्ति, गूढ विज्ञान, एकान्त साधना, लोकप्रियता, करुणा','एकान्तवाद, भ्रम, अनिद्रा, मनोद्वन्द्व','चिकित्सा, विज्ञान, ज्योतिष, जनसेवा','अनियमित, गोप्य स्रोत, चल सम्पत्ति','भावनात्मक दूरी, गहिरो स्नेह, भावनामा उतारचढाव','चन्द्रो शतभिषा नक्षत्रे शुभाशुभं फलं ददाति।','Brihat Parashara Hora Shastra — Nakshatra Phala','सोमबार शिवलिंगमा जल चढाउने।'),
(2,77,'चन्द्र पूर्व भाद्रपदा नक्षत्रमा रहँदा भावनात्मक प्रभाव र नक्षत्र शक्ति मिसिन्छ — अज एकपदको नक्षत्र — तीव्र आदर्श। नक्षत्र स्वामी गुरु चन्द्रको मित्रहुनाले फल सहज र शुभ हुन्छ। यो नक्षत्र कुम्भ राशिको भागमा पर्ने हुनाले दृढ आदर्श जस्ता फाइदा र तीव्रता जस्ता चुनौती दुवै देखिन्छ।',NULL,'दृढ आदर्श, त्याग, गहिरो चिन्तन, लोकप्रियता, करुणा','तीव्रता, अन्यमाथि दबाब, मनोद्वन्द्व, भावनात्मक अस्थिरता','आध्यात्मिक कार्य, अनुसन्धान, जनसेवा, शिक्षा','आदर्शका लागि त्याग, चल सम्पत्ति, जलजन्य आय','भावनात्मक तीव्रता, गहिरो स्नेह, भावनामा उतारचढाव','चन्द्रो पूर्व भाद्रपदा नक्षत्रे शुभाशुभं फलं ददाति।','Brihat Parashara Hora Shastra — Nakshatra Phala','सोमबार शिवलिंगमा जल चढाउने।'),
(2,78,'चन्द्र उत्तर भाद्रपदा नक्षत्रमा रहँदा भावनात्मक प्रभाव र नक्षत्र शक्ति मिसिन्छ — अहिर्बुध्न्यको नक्षत्र — गहिरो ज्ञान। नक्षत्र स्वामी शनि चन्द्रको शत्रु हुनाले चुनौती रहन्छ। यो नक्षत्र मीन राशिको भागमा पर्ने हुनाले धैर्य जस्ता फाइदा र गम्भीरतामा अति जस्ता चुनौती दुवै देखिन्छ।',NULL,'धैर्य, गहिरो ज्ञान, दीर्घ आयु, लोकप्रियता, करुणा','गम्भीरतामा अति, मौनता, मनोद्वन्द्व, भावनात्मक अस्थिरता','विद्या, अनुसन्धान, परामर्श, जनसेवा','दीर्घकालीन बचत, चल सम्पत्ति, जलजन्य आय','गम्भीर र दिगो सम्बन्ध, गहिरो स्नेह, भावनामा उतारचढाव','चन्द्रो उत्तर भाद्रपदा नक्षत्रे शुभाशुभं फलं ददाति।','Brihat Parashara Hora Shastra — Nakshatra Phala','सोमबार शिवलिंगमा जल चढाउने।'),
(2,79,'चन्द्र रेवती नक्षत्रमा रहँदा भावनात्मक प्रभाव र नक्षत्र शक्ति मिसिन्छ — पुषणको नक्षत्र — पूर्णता र पोषण। नक्षत्र स्वामी बुध चन्द्रको शत्रु हुनाले चुनौती रहन्छ। यो नक्षत्र मीन राशिको भागमा पर्ने हुनाले पूर्णता जस्ता फाइदा र अन्त्यमा ढिलाइ जस्ता चुनौती दुवै देखिन्छ।',NULL,'पूर्णता, सुरक्षित यात्रा, पोषण, लोकप्रियता, करुणा','अन्त्यमा ढिलाइ, अति संरक्षण, मनोद्वन्द्व, भावनात्मक अस्थिरता','यात्रा, सेवा, परिवहन, जनसेवा','सुरक्षित, तर सानो, चल सम्पत्ति','पोषक सम्बन्ध, ममता, गहिरो स्नेह','चन्द्रो रेवती नक्षत्रे शुभाशुभं फलं ददाति।','Brihat Parashara Hora Shastra — Nakshatra Phala','सोमबार शिवलिंगमा जल चढाउने।'),
(3,53,'मङ्गल अश्विनी नक्षत्रमा रहँदा पराक्रम र नक्षत्र शक्ति मिसिन्छ — चिकित्सा र गतिको नक्षत्र। नक्षत्र स्वामी केतु मङ्गलको मित्रहुनाले फल सहज र शुभ हुन्छ। यो नक्षत्र मेष राशिको भागमा पर्ने हुनाले द्रुत उपचार शक्ति जस्ता फाइदा र जल्दबाजी जस्ता चुनौती दुवै देखिन्छ।',NULL,'द्रुत उपचार शक्ति, साहस, नयाँ सुरुवात, पराक्रम, विजय','जल्दबाजी, अधुरो काम, क्रोध, विवाद','चिकित्सा, खेलकुद, अनुसन्धान, सेना','नयाँ स्रोतबाट छिटो लाभ, भूमि र पराक्रमबाट लाभ','स्नेहमा तीव्रता, छिटो नजिक, तीव्र भावना','मङ्गलो अश्विनी नक्षत्रे शुभाशुभं फलं ददाति।','Brihat Parashara Hora Shastra — Nakshatra Phala','मङ्गलबार हनुमान चालीसा पाठ गर्ने।'),
(3,54,'मङ्गल भरणी नक्षत्रमा रहँदा पराक्रम र नक्षत्र शक्ति मिसिन्छ — यमको नक्षत्र — भार बोक्ने र परिवर्तन। नक्षत्र स्वामी शुक्रसँग मङ्गल तटस्थ हुनाले फल मध्यम रहन्छ। यो नक्षत्र मेष राशिको भागमा पर्ने हुनाले सहनशीलता जस्ता फाइदा र दमन जस्ता चुनौती दुवै देखिन्छ।',NULL,'सहनशीलता, जिम्मेवारी, परिवर्तन साहस, साहस, पराक्रम','दमन, अति बोझ, क्रोध, विवाद','प्रशासन, सेवा, न्याय, सेना','परिश्रमबाट स्थिर धन, भूमि र पराक्रमबाट लाभ','वफादारी, तर दबाब, तीव्र भावना','मङ्गलो भरणी नक्षत्रे शुभाशुभं फलं ददाति।','Brihat Parashara Hora Shastra — Nakshatra Phala','मङ्गलबार हनुमान चालीसा पाठ गर्ने।'),
(3,55,'मङ्गल कृत्तिका नक्षत्रमा रहँदा पराक्रम र नक्षत्र शक्ति मिसिन्छ — अग्निको नक्षत्र — शुद्धि र काट्ने शक्ति। नक्षत्र स्वामी सूर्य मङ्गलको मित्रहुनाले फल सहज र शुभ हुन्छ। यो नक्षत्र मेष राशिको भागमा पर्ने हुनाले तीक्ष्ण बुद्धि जस्ता फाइदा र कटुवाणी जस्ता चुनौती दुवै देखिन्छ।',NULL,'तीक्ष्ण बुद्धि, शुद्धता, नेतृत्व, साहस, पराक्रम','कटुवाणी, जल्दी निर्णय, क्रोध, विवाद','शिक्षण, चिकित्सा, अग्निसँग सम्बन्धित काम, सेना','स्वाभिमानबाट आय, भूमि र पराक्रमबाट लाभ','आदर चाहने, स्पष्टवादी, तीव्र भावना','मङ्गलो कृत्तिका नक्षत्रे शुभाशुभं फलं ददाति।','Brihat Parashara Hora Shastra — Nakshatra Phala','मङ्गलबार हनुमान चालीसा पाठ गर्ने।'),
(3,56,'मङ्गल रोहिणी नक्षत्रमा रहँदा पराक्रम र नक्षत्र शक्ति मिसिन्छ — ब्रह्माको नक्षत्र — वृद्धि र सौन्दर्य। नक्षत्र स्वामी चन्द्रसँग मङ्गल तटस्थ हुनाले फल मध्यम रहन्छ। यो नक्षत्र वृषभ राशिको भागमा पर्ने हुनाले सृजनात्मकता जस्ता फाइदा र मोह जस्ता चुनौती दुवै देखिन्छ।',NULL,'सृजनात्मकता, सम्पत्ति वृद्धि, सौन्दर्य, साहस, पराक्रम','मोह, अति आसक्ति, क्रोध, विवाद','कला, कृषि, व्यवस्थापन, सेना','सम्पत्ति र कृषिबाट लाभ, भूमि र पराक्रमबाट लाभ','गहिरो स्नेह, सुन्दर सम्बन्ध, तीव्र भावना','मङ्गलो रोहिणी नक्षत्रे शुभाशुभं फलं ददाति।','Brihat Parashara Hora Shastra — Nakshatra Phala','मङ्गलबार हनुमान चालीसा पाठ गर्ने।'),
(3,57,'मङ्गल मृगशिरा नक्षत्रमा रहँदा पराक्रम र नक्षत्र शक्ति मिसिन्छ — सोमको नक्षत्र — खोज र अन्वेषण। नक्षत्र स्वामी स्वयं मङ्गल भएकाले ग्रहको प्रभाव प्रबल हुन्छ। यो नक्षत्र वृषभ राशिको भागमा पर्ने हुनाले अन्वेषण जस्ता फाइदा र अस्थिर ध्यान जस्ता चुनौती दुवै देखिन्छ।',NULL,'अन्वेषण, जिज्ञासा, रचनात्मकता, साहस, पराक्रम','अस्थिर ध्यान, भटकन, क्रोध, विवाद','अनुसन्धान, यात्रा, डिजाइन, सेना','खोजबाट लाभ, तर ढिलाइ, भूमि र पराक्रमबाट लाभ','स्नेहमा खोज, अस्थिरता, तीव्र भावना','मङ्गलो मृगशिरा नक्षत्रे शुभाशुभं फलं ददाति।','Brihat Parashara Hora Shastra — Nakshatra Phala','मङ्गलबार हनुमान चालीसा पाठ गर्ने।'),
(3,58,'मङ्गल आर्द्रा नक्षत्रमा रहँदा पराक्रम र नक्षत्र शक्ति मिसिन्छ — रुद्रको नक्षत्र — विनाश र पुनर्जन्म। नक्षत्र स्वामी स्वयं मङ्गल भएकाले ग्रहको प्रभाव प्रबल हुन्छ। यो नक्षत्र मिथुन राशिको भागमा पर्ने हुनाले संकटमा टिकाउपन जस्ता फाइदा र आवेग जस्ता चुनौती दुवै देखिन्छ।',NULL,'संकटमा टिकाउपन, तीक्ष्ण बुद्धि, परिवर्तन, साहस, पराक्रम','आवेग, विवाद, तनाव, क्रोध','अनुसन्धान, चिकित्सा, सुरक्षा, सेना','उतारचढाव, जोखिमबाट लाभ, भूमि र पराक्रमबाट लाभ','तीव्र भावना, कहिलेकाहीं झगडा, विवाद','मङ्गलो आर्द्रा नक्षत्रे शुभाशुभं फलं ददाति।','Brihat Parashara Hora Shastra — Nakshatra Phala','मङ्गलबार हनुमान चालीसा पाठ गर्ने।'),
(3,59,'मङ्गल पुनर्वसु नक्षत्रमा रहँदा पराक्रम र नक्षत्र शक्ति मिसिन्छ — आदितिको नक्षत्र — फिर्ता र नवीनीकरण। नक्षत्र स्वामी गुरु मङ्गलको मित्रहुनाले फल सहज र शुभ हुन्छ। यो नक्षत्र मिथुन राशिको भागमा पर्ने हुनाले पुनर्स्थापना जस्ता फाइदा र ढिलाइ जस्ता चुनौती दुवै देखिन्छ।',NULL,'पुनर्स्थापना, भाग्य, सुरक्षा, साहस, पराक्रम','ढिलाइ, पुरानो कुरामा फर्कने, क्रोध, विवाद','शिक्षण, यात्रा, सेवा, सेना','पुनः अवसरबाट लाभ, भूमि र पराक्रमबाट लाभ','फेरि मिलाप, करुणा, तीव्र भावना','मङ्गलो पुनर्वसु नक्षत्रे शुभाशुभं फलं ददाति।','Brihat Parashara Hora Shastra — Nakshatra Phala','मङ्गलबार हनुमान चालीसा पाठ गर्ने।'),
(3,60,'मङ्गल पुष्य नक्षत्रमा रहँदा पराक्रम र नक्षत्र शक्ति मिसिन्छ — बृहस्पतिको नक्षत्र — पोषण र शुभता। नक्षत्र स्वामी शनि मङ्गलको शत्रु हुनाले चुनौती रहन्छ। यो नक्षत्र कर्क राशिको भागमा पर्ने हुनाले पोषण जस्ता फाइदा र अति निर्भरता जस्ता चुनौती दुवै देखिन्छ।',NULL,'पोषण, धर्म, सम्मान, शुभ आरम्भ, साहस','अति निर्भरता, दायित्व बढ्ने, क्रोध, विवाद','शिक्षण, बैंकिङ, सेवा, कृषि','स्थिर र शुभ आय, भूमि र पराक्रमबाट लाभ','स्नेहपूर्ण, परिवारमुखी, तीव्र भावना','मङ्गलो पुष्य नक्षत्रे शुभाशुभं फलं ददाति।','Brihat Parashara Hora Shastra — Nakshatra Phala','मङ्गलबार हनुमान चालीसा पाठ गर्ने।'),
(3,61,'मङ्गल अश्लेषा नक्षत्रमा रहँदा पराक्रम र नक्षत्र शक्ति मिसिन्छ — नागको नक्षत्र — भ्रमण र रहस्य। नक्षत्र स्वामी बुधसँग मङ्गल तटस्थ हुनाले फल मध्यम रहन्छ। यो नक्षत्र कर्क राशिको भागमा पर्ने हुनाले अन्तर्दृष्टि जस्ता फाइदा र षड्यन्त्र जस्ता चुनौती दुवै देखिन्छ।',NULL,'अन्तर्दृष्टि, जादुई आकर्षण, गूढ ज्ञान, साहस, पराक्रम','षड्यन्त्र, भ्रम, अति गोपन, क्रोध','अनुसन्धान, चिकित्सा, रहस्य विषय, सेना','गोप्य स्रोतबाट लाभ, भूमि र पराक्रमबाट लाभ','गहिरो आकर्षण, शंका, तीव्र भावना','मङ्गलो अश्लेषा नक्षत्रे शुभाशुभं फलं ददाति।','Brihat Parashara Hora Shastra — Nakshatra Phala','मङ्गलबार हनुमान चालीसा पाठ गर्ने।'),
(3,62,'मङ्गल मघा नक्षत्रमा रहँदा पराक्रम र नक्षत्र शक्ति मिसिन्छ — पितृको नक्षत्र — राज्य र पूर्वज। नक्षत्र स्वामी केतु मङ्गलको मित्रहुनाले फल सहज र शुभ हुन्छ। यो नक्षत्र सिंह राशिको भागमा पर्ने हुनाले पूर्वजको आशीर्वाद जस्ता फाइदा र अहंकार जस्ता चुनौती दुवै देखिन्छ।',NULL,'पूर्वजको आशीर्वाद, नेतृत्व, प्रतिष्ठा, साहस, पराक्रम','अहंकार, परम्परामा जिद, क्रोध, विवाद','राजनीति, प्रशासन, पूर्वजसँग सम्बन्धित काम, सेना','पारिवारिक सम्पत्ति, भूमि र पराक्रमबाट लाभ','परिवार र सम्मानमा आधारित, तीव्र भावना, विवाद','मङ्गलो मघा नक्षत्रे शुभाशुभं फलं ददाति।','Brihat Parashara Hora Shastra — Nakshatra Phala','मङ्गलबार हनुमान चालीसा पाठ गर्ने।'),
(3,63,'मङ्गल पूर्व फल्गुनी नक्षत्रमा रहँदा पराक्रम र नक्षत्र शक्ति मिसिन्छ — भगको नक्षत्र — सुख र सृजना। नक्षत्र स्वामी शुक्रसँग मङ्गल तटस्थ हुनाले फल मध्यम रहन्छ। यो नक्षत्र सिंह राशिको भागमा पर्ने हुनाले कलात्मक सुख जस्ता फाइदा र अति सुख जस्ता चुनौती दुवै देखिन्छ।',NULL,'कलात्मक सुख, रोमान्स, वैभव, साहस, पराक्रम','अति सुख, आलस्य, क्रोध, विवाद','कला, मनोरञ्जन, सौन्दर्य, सेना','सुख साधनबाट लाभ, भूमि र पराक्रमबाट लाभ','प्रेमपूर्ण सम्बन्ध, आकर्षण, तीव्र भावना','मङ्गलो पूर्व फल्गुनी नक्षत्रे शुभाशुभं फलं ददाति।','Brihat Parashara Hora Shastra — Nakshatra Phala','मङ्गलबार हनुमान चालीसा पाठ गर्ने।'),
(3,64,'मङ्गल उत्तरा फल्गुनी नक्षत्रमा रहँदा पराक्रम र नक्षत्र शक्ति मिसिन्छ — आर्यमाको नक्षत्र — सम्झौता र संरक्षण। नक्षत्र स्वामी सूर्य मङ्गलको मित्रहुनाले फल सहज र शुभ हुन्छ। यो नक्षत्र सिंह राशिको भागमा पर्ने हुनाले साझेदारी जस्ता फाइदा र बाध्यता जस्ता चुनौती दुवै देखिन्छ।',NULL,'साझेदारी, संरक्षण, विश्वास, साहस, पराक्रम','बाध्यता, अन्यमाथि निर्भरता, क्रोध, विवाद','कानुन, साझेदारी, संस्था, सेना','साझेदारीबाट लाभ, भूमि र पराक्रमबाट लाभ','विश्वासयोग्य दीर्घ सम्बन्ध, तीव्र भावना, विवाद','मङ्गलो उत्तरा फल्गुनी नक्षत्रे शुभाशुभं फलं ददाति।','Brihat Parashara Hora Shastra — Nakshatra Phala','मङ्गलबार हनुमान चालीसा पाठ गर्ने।'),
(3,65,'मङ्गल हस्त नक्षत्रमा रहँदा पराक्रम र नक्षत्र शक्ति मिसिन्छ — सविताको नक्षत्र — हस्तकला र कौशल। नक्षत्र स्वामी चन्द्रसँग मङ्गल तटस्थ हुनाले फल मध्यम रहन्छ। यो नक्षत्र कन्या राशिको भागमा पर्ने हुनाले हस्तकला जस्ता फाइदा र चञ्चल हात जस्ता चुनौती दुवै देखिन्छ।',NULL,'हस्तकला, दक्षता, शीघ्र सिक्ने, साहस, पराक्रम','चञ्चल हात, अधुरो काम, क्रोध, विवाद','हस्तकला, चिकित्सा, डिजाइन, सेना','सीपबाट आय, भूमि र पराक्रमबाट लाभ','सेवामा आधारित स्नेह, तीव्र भावना, विवाद','मङ्गलो हस्त नक्षत्रे शुभाशुभं फलं ददाति।','Brihat Parashara Hora Shastra — Nakshatra Phala','मङ्गलबार हनुमान चालीसा पाठ गर्ने।'),
(3,66,'मङ्गल चित्रा नक्षत्रमा रहँदा पराक्रम र नक्षत्र शक्ति मिसिन्छ — विश्वकर्माको नक्षत्र — निर्माण र सजावट। नक्षत्र स्वामी स्वयं मङ्गल भएकाले ग्रहको प्रभाव प्रबल हुन्छ। यो नक्षत्र कन्या राशिको भागमा पर्ने हुनाले रचनात्मकता जस्ता फाइदा र दम्भ जस्ता चुनौती दुवै देखिन्छ।',NULL,'रचनात्मकता, सुन्दरता, प्रतिष्ठा, साहस, पराक्रम','दम्भ, बाह्य सजावटमा ध्यान, क्रोध, विवाद','वास्तुकला, डिजाइन, कला, सेना','कलात्मक कामबाट लाभ, भूमि र पराक्रमबाट लाभ','आकर्षण, तर गम्भीरता कम, तीव्र भावना','मङ्गलो चित्रा नक्षत्रे शुभाशुभं फलं ददाति।','Brihat Parashara Hora Shastra — Nakshatra Phala','मङ्गलबार हनुमान चालीसा पाठ गर्ने।'),
(3,67,'मङ्गल स्वाति नक्षत्रमा रहँदा पराक्रम र नक्षत्र शक्ति मिसिन्छ — वायुको नक्षत्र — स्वतन्त्रता र व्यापार। नक्षत्र स्वामी राहुसँग मङ्गल तटस्थ हुनाले फल मध्यम रहन्छ। यो नक्षत्र तुला राशिको भागमा पर्ने हुनाले स्वतन्त्रता जस्ता फाइदा र भटकन जस्ता चुनौती दुवै देखिन्छ।',NULL,'स्वतन्त्रता, व्यापारिक बुद्धि, सहनशीलता, साहस, पराक्रम','भटकन, अस्थिरता, क्रोध, विवाद','व्यापार, नीति, प्रविधि, सेना','व्यापारबाट चल आय, भूमि र पराक्रमबाट लाभ','स्वतन्त्रता चाहने सम्बन्ध, तीव्र भावना, विवाद','मङ्गलो स्वाति नक्षत्रे शुभाशुभं फलं ददाति।','Brihat Parashara Hora Shastra — Nakshatra Phala','मङ्गलबार हनुमान चालीसा पाठ गर्ने।'),
(3,68,'मङ्गल विशाखा नक्षत्रमा रहँदा पराक्रम र नक्षत्र शक्ति मिसिन्छ — इन्द्राग्निको नक्षत्र — लक्ष्य र उपलब्धि। नक्षत्र स्वामी गुरु मङ्गलको मित्रहुनाले फल सहज र शुभ हुन्छ। यो नक्षत्र तुला राशिको भागमा पर्ने हुनाले लक्ष्य निश्चय जस्ता फाइदा र धैर्य कम जस्ता चुनौती दुवै देखिन्छ।',NULL,'लक्ष्य निश्चय, उपलब्धि, नेतृत्व, साहस, पराक्रम','धैर्य कम, अति महत्वाकांक्षा, क्रोध, विवाद','व्यवस्थापन, इन्जिनियरिङ, नेतृत्व, सेना','लक्ष्य पूर्तिबाट धन, भूमि र पराक्रमबाट लाभ','लक्ष्यमुखी साझेदारी, तीव्र भावना, विवाद','मङ्गलो विशाखा नक्षत्रे शुभाशुभं फलं ददाति।','Brihat Parashara Hora Shastra — Nakshatra Phala','मङ्गलबार हनुमान चालीसा पाठ गर्ने।'),
(3,69,'मङ्गल अनुराधा नक्षत्रमा रहँदा पराक्रम र नक्षत्र शक्ति मिसिन्छ — मित्रको नक्षत्र — मित्रता र भक्ति। नक्षत्र स्वामी शनि मङ्गलको शत्रु हुनाले चुनौती रहन्छ। यो नक्षत्र वृश्चिक राशिको भागमा पर्ने हुनाले मित्रता जस्ता फाइदा र मित्रमाथि अति अपेक्षा जस्ता चुनौती दुवै देखिन्छ।',NULL,'मित्रता, भक्ति, सङ्गठन क्षमता, साहस, पराक्रम','मित्रमाथि अति अपेक्षा, क्रोध, विवाद, दुर्घटना','सङ्गठन, सेवा, धार्मिक कार्य, सेना','मित्रबाट लाभ, भूमि र पराक्रमबाट लाभ','गहिरो मित्रता, विश्वास, तीव्र भावना','मङ्गलो अनुराधा नक्षत्रे शुभाशुभं फलं ददाति।','Brihat Parashara Hora Shastra — Nakshatra Phala','मङ्गलबार हनुमान चालीसा पाठ गर्ने।'),
(3,70,'मङ्गल ज्येष्ठा नक्षत्रमा रहँदा पराक्रम र नक्षत्र शक्ति मिसिन्छ — इन्द्रको नक्षत्र — वरिष्ठता र संरक्षण। नक्षत्र स्वामी बुधसँग मङ्गल तटस्थ हुनाले फल मध्यम रहन्छ। यो नक्षत्र वृश्चिक राशिको भागमा पर्ने हुनाले नेतृत्व जस्ता फाइदा र अहंकार जस्ता चुनौती दुवै देखिन्छ।',NULL,'नेतृत्व, संरक्षण, अनुभव, साहस, पराक्रम','अहंकार, ईर्ष्या, क्रोध, विवाद','प्रशासन, न्याय, वरिष्ठ पद, सेना','स्थापित स्रोतबाट लाभ, भूमि र पराक्रमबाट लाभ','संरक्षक भूमिका, तीव्र भावना, विवाद','मङ्गलो ज्येष्ठा नक्षत्रे शुभाशुभं फलं ददाति।','Brihat Parashara Hora Shastra — Nakshatra Phala','मङ्गलबार हनुमान चालीसा पाठ गर्ने।'),
(3,71,'मङ्गल मूल नक्षत्रमा रहँदा पराक्रम र नक्षत्र शक्ति मिसिन्छ — निर्तिको नक्षत्र — जरा र विनाश। नक्षत्र स्वामी केतु मङ्गलको मित्रहुनाले फल सहज र शुभ हुन्छ। यो नक्षत्र धनु राशिको भागमा पर्ने हुनाले जरा खोज्ने शक्ति जस्ता फाइदा र विनाशकारी प्रवृत्ति जस्ता चुनौती दुवै देखिन्छ।',NULL,'जरा खोज्ने शक्ति, परिवर्तन, पुनर्निर्माण, साहस, पराक्रम','विनाशकारी प्रवृत्ति, आवेग, क्रोध, विवाद','अनुसन्धान, चिकित्सा, क्रान्तिकारी काम, सेना','उतारचढाव, पुनः सम्पत्ति, भूमि र पराक्रमबाट लाभ','तीव्र, कहिलेकाहीं विच्छेद, तीव्र भावना','मङ्गलो मूल नक्षत्रे शुभाशुभं फलं ददाति।','Brihat Parashara Hora Shastra — Nakshatra Phala','मङ्गलबार हनुमान चालीसा पाठ गर्ने।'),
(3,72,'मङ्गल पूर्वाषाढा नक्षत्रमा रहँदा पराक्रम र नक्षत्र शक्ति मिसिन्छ — अपस् नक्षत्र — अजेयता र प्रसार। नक्षत्र स्वामी शुक्रसँग मङ्गल तटस्थ हुनाले फल मध्यम रहन्छ। यो नक्षत्र धनु राशिको भागमा पर्ने हुनाले अजेय साहस जस्ता फाइदा र अति आत्मविश्वास जस्ता चुनौती दुवै देखिन्छ।',NULL,'अजेय साहस, प्रसार, विजय, साहस, पराक्रम','अति आत्मविश्वास, टकराव, क्रोध, विवाद','सेना, नीति, प्रसार, खेलकुद','विस्तारबाट लाभ, भूमि र पराक्रमबाट लाभ','बलियो आवरण, तर दमन, तीव्र भावना','मङ्गलो पूर्वाषाढा नक्षत्रे शुभाशुभं फलं ददाति।','Brihat Parashara Hora Shastra — Nakshatra Phala','मङ्गलबार हनुमान चालीसा पाठ गर्ने।'),
(3,73,'मङ्गल उत्तराषाढा नक्षत्रमा रहँदा पराक्रम र नक्षत्र शक्ति मिसिन्छ — विश्वदेवको नक्षत्र — अन्तिम विजय। नक्षत्र स्वामी सूर्य मङ्गलको मित्रहुनाले फल सहज र शुभ हुन्छ। यो नक्षत्र धनु राशिको भागमा पर्ने हुनाले दिगो विजय जस्ता फाइदा र ढिलो फल जस्ता चुनौती दुवै देखिन्छ।',NULL,'दिगो विजय, सम्मान, धैर्यको फल, साहस, पराक्रम','ढिलो फल, अन्तिम समयमा दबाब, क्रोध, विवाद','प्रशासन, दीर्घ परियोजना, सेना, खेलकुद','दिगो र स्थिर सम्पत्ति, भूमि र पराक्रमबाट लाभ','दीर्घकालीन, स्थिर, तीव्र भावना','मङ्गलो उत्तराषाढा नक्षत्रे शुभाशुभं फलं ददाति।','Brihat Parashara Hora Shastra — Nakshatra Phala','मङ्गलबार हनुमान चालीसा पाठ गर्ने।'),
(3,74,'मङ्गल श्रवण नक्षत्रमा रहँदा पराक्रम र नक्षत्र शक्ति मिसिन्छ — विष्णुको नक्षत्र — सुन्ने र सिक्ने। नक्षत्र स्वामी चन्द्रसँग मङ्गल तटस्थ हुनाले फल मध्यम रहन्छ। यो नक्षत्र मकर राशिको भागमा पर्ने हुनाले ज्ञान जस्ता फाइदा र अति सुन्ने जस्ता चुनौती दुवै देखिन्छ।',NULL,'ज्ञान, श्रवण कला, सम्मान, साहस, पराक्रम','अति सुन्ने, आलोचनामा संवेदनशील, क्रोध, विवाद','शिक्षण, मीडिया, परामर्श, सेना','ज्ञानबाट आय, भूमि र पराक्रमबाट लाभ','कुरा सुन्ने सम्बन्ध, तीव्र भावना, विवाद','मङ्गलो श्रवण नक्षत्रे शुभाशुभं फलं ददाति।','Brihat Parashara Hora Shastra — Nakshatra Phala','मङ्गलबार हनुमान चालीसा पाठ गर्ने।'),
(3,75,'मङ्गल धनिष्ठा नक्षत्रमा रहँदा पराक्रम र नक्षत्र शक्ति मिसिन्छ — वसुको नक्षत्र — धन र समूह। नक्षत्र स्वामी स्वयं मङ्गल भएकाले ग्रहको प्रभाव प्रबल हुन्छ। यो नक्षत्र मकर राशिको भागमा पर्ने हुनाले धन संचय जस्ता फाइदा र समूहमा द्वन्द्व जस्ता चुनौती दुवै देखिन्छ।',NULL,'धन संचय, समूह नेतृत्व, कीर्ति, साहस, पराक्रम','समूहमा द्वन्द्व, अहंकार, क्रोध, विवाद','व्यवस्थापन, समूह कार्य, संगीत, सेना','समूह र धनबाट लाभ, भूमि र पराक्रमबाट लाभ','सामूहिक कार्यमा मिलन, तीव्र भावना, विवाद','मङ्गलो धनिष्ठा नक्षत्रे शुभाशुभं फलं ददाति।','Brihat Parashara Hora Shastra — Nakshatra Phala','मङ्गलबार हनुमान चालीसा पाठ गर्ने।'),
(3,76,'मङ्गल शतभिषा नक्षत्रमा रहँदा पराक्रम र नक्षत्र शक्ति मिसिन्छ — वरुणको नक्षत्र — औषधि र रहस्य। नक्षत्र स्वामी राहुसँग मङ्गल तटस्थ हुनाले फल मध्यम रहन्छ। यो नक्षत्र कुम्भ राशिको भागमा पर्ने हुनाले उपचार शक्ति जस्ता फाइदा र एकान्तवाद जस्ता चुनौती दुवै देखिन्छ।',NULL,'उपचार शक्ति, गूढ विज्ञान, एकान्त साधना, साहस, पराक्रम','एकान्तवाद, भ्रम, अनिद्रा, क्रोध','चिकित्सा, विज्ञान, ज्योतिष, सेना','अनियमित, गोप्य स्रोत, भूमि र पराक्रमबाट लाभ','भावनात्मक दूरी, तीव्र भावना, विवाद','मङ्गलो शतभिषा नक्षत्रे शुभाशुभं फलं ददाति।','Brihat Parashara Hora Shastra — Nakshatra Phala','मङ्गलबार हनुमान चालीसा पाठ गर्ने।'),
(3,77,'मङ्गल पूर्व भाद्रपदा नक्षत्रमा रहँदा पराक्रम र नक्षत्र शक्ति मिसिन्छ — अज एकपदको नक्षत्र — तीव्र आदर्श। नक्षत्र स्वामी गुरु मङ्गलको मित्रहुनाले फल सहज र शुभ हुन्छ। यो नक्षत्र कुम्भ राशिको भागमा पर्ने हुनाले दृढ आदर्श जस्ता फाइदा र तीव्रता जस्ता चुनौती दुवै देखिन्छ।',NULL,'दृढ आदर्श, त्याग, गहिरो चिन्तन, साहस, पराक्रम','तीव्रता, अन्यमाथि दबाब, क्रोध, विवाद','आध्यात्मिक कार्य, अनुसन्धान, सेना, खेलकुद','आदर्शका लागि त्याग, भूमि र पराक्रमबाट लाभ','भावनात्मक तीव्रता, तीव्र भावना, विवाद','मङ्गलो पूर्व भाद्रपदा नक्षत्रे शुभाशुभं फलं ददाति।','Brihat Parashara Hora Shastra — Nakshatra Phala','मङ्गलबार हनुमान चालीसा पाठ गर्ने।'),
(3,78,'मङ्गल उत्तर भाद्रपदा नक्षत्रमा रहँदा पराक्रम र नक्षत्र शक्ति मिसिन्छ — अहिर्बुध्न्यको नक्षत्र — गहिरो ज्ञान। नक्षत्र स्वामी शनि मङ्गलको शत्रु हुनाले चुनौती रहन्छ। यो नक्षत्र मीन राशिको भागमा पर्ने हुनाले धैर्य जस्ता फाइदा र गम्भीरतामा अति जस्ता चुनौती दुवै देखिन्छ।',NULL,'धैर्य, गहिरो ज्ञान, दीर्घ आयु, साहस, पराक्रम','गम्भीरतामा अति, मौनता, क्रोध, विवाद','विद्या, अनुसन्धान, परामर्श, सेना','दीर्घकालीन बचत, भूमि र पराक्रमबाट लाभ','गम्भीर र दिगो सम्बन्ध, तीव्र भावना, विवाद','मङ्गलो उत्तर भाद्रपदा नक्षत्रे शुभाशुभं फलं ददाति।','Brihat Parashara Hora Shastra — Nakshatra Phala','मङ्गलबार हनुमान चालीसा पाठ गर्ने।'),
(3,79,'मङ्गल रेवती नक्षत्रमा रहँदा पराक्रम र नक्षत्र शक्ति मिसिन्छ — पुषणको नक्षत्र — पूर्णता र पोषण। नक्षत्र स्वामी बुधसँग मङ्गल तटस्थ हुनाले फल मध्यम रहन्छ। यो नक्षत्र मीन राशिको भागमा पर्ने हुनाले पूर्णता जस्ता फाइदा र अन्त्यमा ढिलाइ जस्ता चुनौती दुवै देखिन्छ।',NULL,'पूर्णता, सुरक्षित यात्रा, पोषण, साहस, पराक्रम','अन्त्यमा ढिलाइ, अति संरक्षण, क्रोध, विवाद','यात्रा, सेवा, परिवहन, सेना','सुरक्षित, तर सानो, भूमि र पराक्रमबाट लाभ','पोषक सम्बन्ध, ममता, तीव्र भावना','मङ्गलो रेवती नक्षत्रे शुभाशुभं फलं ददाति।','Brihat Parashara Hora Shastra — Nakshatra Phala','मङ्गलबार हनुमान चालीसा पाठ गर्ने।'),
(4,53,'बुध अश्विनी नक्षत्रमा रहँदा बौद्धिक क्षमता र नक्षत्र शक्ति मिसिन्छ — चिकित्सा र गतिको नक्षत्र। नक्षत्र स्वामी केतुसँग बुध तटस्थ हुनाले फल मध्यम रहन्छ। यो नक्षत्र मेष राशिको भागमा पर्ने हुनाले द्रुत उपचार शक्ति जस्ता फाइदा र जल्दबाजी जस्ता चुनौती दुवै देखिन्छ।',NULL,'द्रुत उपचार शक्ति, साहस, नयाँ सुरुवात, बुद्धिमत्ता, वाणी कला','जल्दबाजी, अधुरो काम, द्विधा, अति बोली','चिकित्सा, खेलकुद, अनुसन्धान, लेखन','नयाँ स्रोतबाट छिटो लाभ, व्यापारबाट लाभ, बहुआय','स्नेहमा तीव्रता, छिटो नजिक, संवादमा दक्ष','बुधो अश्विनी नक्षत्रे शुभाशुभं फलं ददाति।','Brihat Parashara Hora Shastra — Nakshatra Phala','बुधवार गणेशलाई दूर्वा चढाउने।'),
(4,54,'बुध भरणी नक्षत्रमा रहँदा बौद्धिक क्षमता र नक्षत्र शक्ति मिसिन्छ — यमको नक्षत्र — भार बोक्ने र परिवर्तन। नक्षत्र स्वामी शुक्र बुधको मित्रहुनाले फल सहज र शुभ हुन्छ। यो नक्षत्र मेष राशिको भागमा पर्ने हुनाले सहनशीलता जस्ता फाइदा र दमन जस्ता चुनौती दुवै देखिन्छ।',NULL,'सहनशीलता, जिम्मेवारी, परिवर्तन साहस, बुद्धिमत्ता, वाणी कला','दमन, अति बोझ, द्विधा, अति बोली','प्रशासन, सेवा, न्याय, लेखन','परिश्रमबाट स्थिर धन, व्यापारबाट लाभ, बहुआय','वफादारी, तर दबाब, संवादमा दक्ष','बुधो भरणी नक्षत्रे शुभाशुभं फलं ददाति।','Brihat Parashara Hora Shastra — Nakshatra Phala','बुधवार गणेशलाई दूर्वा चढाउने।'),
(4,55,'बुध कृत्तिका नक्षत्रमा रहँदा बौद्धिक क्षमता र नक्षत्र शक्ति मिसिन्छ — अग्निको नक्षत्र — शुद्धि र काट्ने शक्ति। नक्षत्र स्वामी सूर्यसँग बुध तटस्थ हुनाले फल मध्यम रहन्छ। यो नक्षत्र मेष राशिको भागमा पर्ने हुनाले तीक्ष्ण बुद्धि जस्ता फाइदा र कटुवाणी जस्ता चुनौती दुवै देखिन्छ।',NULL,'तीक्ष्ण बुद्धि, शुद्धता, नेतृत्व, बुद्धिमत्ता, वाणी कला','कटुवाणी, जल्दी निर्णय, द्विधा, अति बोली','शिक्षण, चिकित्सा, अग्निसँग सम्बन्धित काम, लेखन','स्वाभिमानबाट आय, व्यापारबाट लाभ, बहुआय','आदर चाहने, स्पष्टवादी, संवादमा दक्ष','बुधो कृत्तिका नक्षत्रे शुभाशुभं फलं ददाति।','Brihat Parashara Hora Shastra — Nakshatra Phala','बुधवार गणेशलाई दूर्वा चढाउने।'),
(4,56,'बुध रोहिणी नक्षत्रमा रहँदा बौद्धिक क्षमता र नक्षत्र शक्ति मिसिन्छ — ब्रह्माको नक्षत्र — वृद्धि र सौन्दर्य। नक्षत्र स्वामी चन्द्र बुधको मित्रहुनाले फल सहज र शुभ हुन्छ। यो नक्षत्र वृषभ राशिको भागमा पर्ने हुनाले सृजनात्मकता जस्ता फाइदा र मोह जस्ता चुनौती दुवै देखिन्छ।',NULL,'सृजनात्मकता, सम्पत्ति वृद्धि, सौन्दर्य, बुद्धिमत्ता, वाणी कला','मोह, अति आसक्ति, द्विधा, अति बोली','कला, कृषि, व्यवस्थापन, लेखन','सम्पत्ति र कृषिबाट लाभ, व्यापारबाट लाभ, बहुआय','गहिरो स्नेह, सुन्दर सम्बन्ध, संवादमा दक्ष','बुधो रोहिणी नक्षत्रे शुभाशुभं फलं ददाति।','Brihat Parashara Hora Shastra — Nakshatra Phala','बुधवार गणेशलाई दूर्वा चढाउने।'),
(4,57,'बुध मृगशिरा नक्षत्रमा रहँदा बौद्धिक क्षमता र नक्षत्र शक्ति मिसिन्छ — सोमको नक्षत्र — खोज र अन्वेषण। नक्षत्र स्वामी मङ्गल बुधको शत्रु हुनाले चुनौती रहन्छ। यो नक्षत्र वृषभ राशिको भागमा पर्ने हुनाले अन्वेषण जस्ता फाइदा र अस्थिर ध्यान जस्ता चुनौती दुवै देखिन्छ।',NULL,'अन्वेषण, जिज्ञासा, रचनात्मकता, बुद्धिमत्ता, वाणी कला','अस्थिर ध्यान, भटकन, द्विधा, अति बोली','अनुसन्धान, यात्रा, डिजाइन, लेखन','खोजबाट लाभ, तर ढिलाइ, व्यापारबाट लाभ','स्नेहमा खोज, अस्थिरता, संवादमा दक्ष','बुधो मृगशिरा नक्षत्रे शुभाशुभं फलं ददाति।','Brihat Parashara Hora Shastra — Nakshatra Phala','बुधवार गणेशलाई दूर्वा चढाउने।'),
(4,58,'बुध आर्द्रा नक्षत्रमा रहँदा बौद्धिक क्षमता र नक्षत्र शक्ति मिसिन्छ — रुद्रको नक्षत्र — विनाश र पुनर्जन्म। नक्षत्र स्वामी मङ्गल बुधको शत्रु हुनाले चुनौती रहन्छ। यो नक्षत्र मिथुन राशिको भागमा पर्ने हुनाले संकटमा टिकाउपन जस्ता फाइदा र आवेग जस्ता चुनौती दुवै देखिन्छ।',NULL,'संकटमा टिकाउपन, तीक्ष्ण बुद्धि, परिवर्तन, बुद्धिमत्ता, वाणी कला','आवेग, विवाद, तनाव, द्विधा','अनुसन्धान, चिकित्सा, सुरक्षा, लेखन','उतारचढाव, जोखिमबाट लाभ, व्यापारबाट लाभ','तीव्र भावना, कहिलेकाहीं झगडा, संवादमा दक्ष','बुधो आर्द्रा नक्षत्रे शुभाशुभं फलं ददाति।','Brihat Parashara Hora Shastra — Nakshatra Phala','बुधवार गणेशलाई दूर्वा चढाउने।'),
(4,59,'बुध पुनर्वसु नक्षत्रमा रहँदा बौद्धिक क्षमता र नक्षत्र शक्ति मिसिन्छ — आदितिको नक्षत्र — फिर्ता र नवीनीकरण। नक्षत्र स्वामी गुरु बुधको शत्रु हुनाले चुनौती रहन्छ। यो नक्षत्र मिथुन राशिको भागमा पर्ने हुनाले पुनर्स्थापना जस्ता फाइदा र ढिलाइ जस्ता चुनौती दुवै देखिन्छ।',NULL,'पुनर्स्थापना, भाग्य, सुरक्षा, बुद्धिमत्ता, वाणी कला','ढिलाइ, पुरानो कुरामा फर्कने, द्विधा, अति बोली','शिक्षण, यात्रा, सेवा, लेखन','पुनः अवसरबाट लाभ, व्यापारबाट लाभ, बहुआय','फेरि मिलाप, करुणा, संवादमा दक्ष','बुधो पुनर्वसु नक्षत्रे शुभाशुभं फलं ददाति।','Brihat Parashara Hora Shastra — Nakshatra Phala','बुधवार गणेशलाई दूर्वा चढाउने।'),
(4,60,'बुध पुष्य नक्षत्रमा रहँदा बौद्धिक क्षमता र नक्षत्र शक्ति मिसिन्छ — बृहस्पतिको नक्षत्र — पोषण र शुभता। नक्षत्र स्वामी शनि बुधको मित्रहुनाले फल सहज र शुभ हुन्छ। यो नक्षत्र कर्क राशिको भागमा पर्ने हुनाले पोषण जस्ता फाइदा र अति निर्भरता जस्ता चुनौती दुवै देखिन्छ।',NULL,'पोषण, धर्म, सम्मान, शुभ आरम्भ, बुद्धिमत्ता','अति निर्भरता, दायित्व बढ्ने, द्विधा, अति बोली','शिक्षण, बैंकिङ, सेवा, कृषि','स्थिर र शुभ आय, व्यापारबाट लाभ, बहुआय','स्नेहपूर्ण, परिवारमुखी, संवादमा दक्ष','बुधो पुष्य नक्षत्रे शुभाशुभं फलं ददाति।','Brihat Parashara Hora Shastra — Nakshatra Phala','बुधवार गणेशलाई दूर्वा चढाउने।'),
(4,61,'बुध अश्लेषा नक्षत्रमा रहँदा बौद्धिक क्षमता र नक्षत्र शक्ति मिसिन्छ — नागको नक्षत्र — भ्रमण र रहस्य। नक्षत्र स्वामी स्वयं बुध भएकाले ग्रहको प्रभाव प्रबल हुन्छ। यो नक्षत्र कर्क राशिको भागमा पर्ने हुनाले अन्तर्दृष्टि जस्ता फाइदा र षड्यन्त्र जस्ता चुनौती दुवै देखिन्छ।',NULL,'अन्तर्दृष्टि, जादुई आकर्षण, गूढ ज्ञान, बुद्धिमत्ता, वाणी कला','षड्यन्त्र, भ्रम, अति गोपन, द्विधा','अनुसन्धान, चिकित्सा, रहस्य विषय, लेखन','गोप्य स्रोतबाट लाभ, व्यापारबाट लाभ, बहुआय','गहिरो आकर्षण, शंका, संवादमा दक्ष','बुधो अश्लेषा नक्षत्रे शुभाशुभं फलं ददाति।','Brihat Parashara Hora Shastra — Nakshatra Phala','बुधवार गणेशलाई दूर्वा चढाउने।'),
(4,62,'बुध मघा नक्षत्रमा रहँदा बौद्धिक क्षमता र नक्षत्र शक्ति मिसिन्छ — पितृको नक्षत्र — राज्य र पूर्वज। नक्षत्र स्वामी केतुसँग बुध तटस्थ हुनाले फल मध्यम रहन्छ। यो नक्षत्र सिंह राशिको भागमा पर्ने हुनाले पूर्वजको आशीर्वाद जस्ता फाइदा र अहंकार जस्ता चुनौती दुवै देखिन्छ।',NULL,'पूर्वजको आशीर्वाद, नेतृत्व, प्रतिष्ठा, बुद्धिमत्ता, वाणी कला','अहंकार, परम्परामा जिद, द्विधा, अति बोली','राजनीति, प्रशासन, पूर्वजसँग सम्बन्धित काम, लेखन','पारिवारिक सम्पत्ति, व्यापारबाट लाभ, बहुआय','परिवार र सम्मानमा आधारित, संवादमा दक्ष, तर भावना कम','बुधो मघा नक्षत्रे शुभाशुभं फलं ददाति।','Brihat Parashara Hora Shastra — Nakshatra Phala','बुधवार गणेशलाई दूर्वा चढाउने।'),
(4,63,'बुध पूर्व फल्गुनी नक्षत्रमा रहँदा बौद्धिक क्षमता र नक्षत्र शक्ति मिसिन्छ — भगको नक्षत्र — सुख र सृजना। नक्षत्र स्वामी शुक्र बुधको मित्रहुनाले फल सहज र शुभ हुन्छ। यो नक्षत्र सिंह राशिको भागमा पर्ने हुनाले कलात्मक सुख जस्ता फाइदा र अति सुख जस्ता चुनौती दुवै देखिन्छ।',NULL,'कलात्मक सुख, रोमान्स, वैभव, बुद्धिमत्ता, वाणी कला','अति सुख, आलस्य, द्विधा, अति बोली','कला, मनोरञ्जन, सौन्दर्य, लेखन','सुख साधनबाट लाभ, व्यापारबाट लाभ, बहुआय','प्रेमपूर्ण सम्बन्ध, आकर्षण, संवादमा दक्ष','बुधो पूर्व फल्गुनी नक्षत्रे शुभाशुभं फलं ददाति।','Brihat Parashara Hora Shastra — Nakshatra Phala','बुधवार गणेशलाई दूर्वा चढाउने।'),
(4,64,'बुध उत्तरा फल्गुनी नक्षत्रमा रहँदा बौद्धिक क्षमता र नक्षत्र शक्ति मिसिन्छ — आर्यमाको नक्षत्र — सम्झौता र संरक्षण। नक्षत्र स्वामी सूर्यसँग बुध तटस्थ हुनाले फल मध्यम रहन्छ। यो नक्षत्र सिंह राशिको भागमा पर्ने हुनाले साझेदारी जस्ता फाइदा र बाध्यता जस्ता चुनौती दुवै देखिन्छ।',NULL,'साझेदारी, संरक्षण, विश्वास, बुद्धिमत्ता, वाणी कला','बाध्यता, अन्यमाथि निर्भरता, द्विधा, अति बोली','कानुन, साझेदारी, संस्था, लेखन','साझेदारीबाट लाभ, व्यापारबाट लाभ, बहुआय','विश्वासयोग्य दीर्घ सम्बन्ध, संवादमा दक्ष, तर भावना कम','बुधो उत्तरा फल्गुनी नक्षत्रे शुभाशुभं फलं ददाति।','Brihat Parashara Hora Shastra — Nakshatra Phala','बुधवार गणेशलाई दूर्वा चढाउने।'),
(4,65,'बुध हस्त नक्षत्रमा रहँदा बौद्धिक क्षमता र नक्षत्र शक्ति मिसिन्छ — सविताको नक्षत्र — हस्तकला र कौशल। नक्षत्र स्वामी चन्द्र बुधको मित्रहुनाले फल सहज र शुभ हुन्छ। यो नक्षत्र कन्या राशिको भागमा पर्ने हुनाले हस्तकला जस्ता फाइदा र चञ्चल हात जस्ता चुनौती दुवै देखिन्छ।',NULL,'हस्तकला, दक्षता, शीघ्र सिक्ने, बुद्धिमत्ता, वाणी कला','चञ्चल हात, अधुरो काम, द्विधा, अति बोली','हस्तकला, चिकित्सा, डिजाइन, लेखन','सीपबाट आय, व्यापारबाट लाभ, बहुआय','सेवामा आधारित स्नेह, संवादमा दक्ष, तर भावना कम','बुधो हस्त नक्षत्रे शुभाशुभं फलं ददाति।','Brihat Parashara Hora Shastra — Nakshatra Phala','बुधवार गणेशलाई दूर्वा चढाउने।'),
(4,66,'बुध चित्रा नक्षत्रमा रहँदा बौद्धिक क्षमता र नक्षत्र शक्ति मिसिन्छ — विश्वकर्माको नक्षत्र — निर्माण र सजावट। नक्षत्र स्वामी मङ्गल बुधको शत्रु हुनाले चुनौती रहन्छ। यो नक्षत्र कन्या राशिको भागमा पर्ने हुनाले रचनात्मकता जस्ता फाइदा र दम्भ जस्ता चुनौती दुवै देखिन्छ।',NULL,'रचनात्मकता, सुन्दरता, प्रतिष्ठा, बुद्धिमत्ता, वाणी कला','दम्भ, बाह्य सजावटमा ध्यान, द्विधा, अति बोली','वास्तुकला, डिजाइन, कला, लेखन','कलात्मक कामबाट लाभ, व्यापारबाट लाभ, बहुआय','आकर्षण, तर गम्भीरता कम, संवादमा दक्ष','बुधो चित्रा नक्षत्रे शुभाशुभं फलं ददाति।','Brihat Parashara Hora Shastra — Nakshatra Phala','बुधवार गणेशलाई दूर्वा चढाउने।'),
(4,67,'बुध स्वाति नक्षत्रमा रहँदा बौद्धिक क्षमता र नक्षत्र शक्ति मिसिन्छ — वायुको नक्षत्र — स्वतन्त्रता र व्यापार। नक्षत्र स्वामी राहु बुधको मित्रहुनाले फल सहज र शुभ हुन्छ। यो नक्षत्र तुला राशिको भागमा पर्ने हुनाले स्वतन्त्रता जस्ता फाइदा र भटकन जस्ता चुनौती दुवै देखिन्छ।',NULL,'स्वतन्त्रता, व्यापारिक बुद्धि, सहनशीलता, बुद्धिमत्ता, वाणी कला','भटकन, अस्थिरता, द्विधा, अति बोली','व्यापार, नीति, प्रविधि, लेखन','व्यापारबाट चल आय, व्यापारबाट लाभ, बहुआय','स्वतन्त्रता चाहने सम्बन्ध, संवादमा दक्ष, तर भावना कम','बुधो स्वाति नक्षत्रे शुभाशुभं फलं ददाति।','Brihat Parashara Hora Shastra — Nakshatra Phala','बुधवार गणेशलाई दूर्वा चढाउने।'),
(4,68,'बुध विशाखा नक्षत्रमा रहँदा बौद्धिक क्षमता र नक्षत्र शक्ति मिसिन्छ — इन्द्राग्निको नक्षत्र — लक्ष्य र उपलब्धि। नक्षत्र स्वामी गुरु बुधको शत्रु हुनाले चुनौती रहन्छ। यो नक्षत्र तुला राशिको भागमा पर्ने हुनाले लक्ष्य निश्चय जस्ता फाइदा र धैर्य कम जस्ता चुनौती दुवै देखिन्छ।',NULL,'लक्ष्य निश्चय, उपलब्धि, नेतृत्व, बुद्धिमत्ता, वाणी कला','धैर्य कम, अति महत्वाकांक्षा, द्विधा, अति बोली','व्यवस्थापन, इन्जिनियरिङ, नेतृत्व, लेखन','लक्ष्य पूर्तिबाट धन, व्यापारबाट लाभ, बहुआय','लक्ष्यमुखी साझेदारी, संवादमा दक्ष, तर भावना कम','बुधो विशाखा नक्षत्रे शुभाशुभं फलं ददाति।','Brihat Parashara Hora Shastra — Nakshatra Phala','बुधवार गणेशलाई दूर्वा चढाउने।'),
(4,69,'बुध अनुराधा नक्षत्रमा रहँदा बौद्धिक क्षमता र नक्षत्र शक्ति मिसिन्छ — मित्रको नक्षत्र — मित्रता र भक्ति। नक्षत्र स्वामी शनि बुधको मित्रहुनाले फल सहज र शुभ हुन्छ। यो नक्षत्र वृश्चिक राशिको भागमा पर्ने हुनाले मित्रता जस्ता फाइदा र मित्रमाथि अति अपेक्षा जस्ता चुनौती दुवै देखिन्छ।',NULL,'मित्रता, भक्ति, सङ्गठन क्षमता, बुद्धिमत्ता, वाणी कला','मित्रमाथि अति अपेक्षा, द्विधा, अति बोली','सङ्गठन, सेवा, धार्मिक कार्य, लेखन','मित्रबाट लाभ, व्यापारबाट लाभ, बहुआय','गहिरो मित्रता, विश्वास, संवादमा दक्ष','बुधो अनुराधा नक्षत्रे शुभाशुभं फलं ददाति।','Brihat Parashara Hora Shastra — Nakshatra Phala','बुधवार गणेशलाई दूर्वा चढाउने।'),
(4,70,'बुध ज्येष्ठा नक्षत्रमा रहँदा बौद्धिक क्षमता र नक्षत्र शक्ति मिसिन्छ — इन्द्रको नक्षत्र — वरिष्ठता र संरक्षण। नक्षत्र स्वामी स्वयं बुध भएकाले ग्रहको प्रभाव प्रबल हुन्छ। यो नक्षत्र वृश्चिक राशिको भागमा पर्ने हुनाले नेतृत्व जस्ता फाइदा र अहंकार जस्ता चुनौती दुवै देखिन्छ।',NULL,'नेतृत्व, संरक्षण, अनुभव, बुद्धिमत्ता, वाणी कला','अहंकार, ईर्ष्या, द्विधा, अति बोली','प्रशासन, न्याय, वरिष्ठ पद, लेखन','स्थापित स्रोतबाट लाभ, व्यापारबाट लाभ, बहुआय','संरक्षक भूमिका, संवादमा दक्ष, तर भावना कम','बुधो ज्येष्ठा नक्षत्रे शुभाशुभं फलं ददाति।','Brihat Parashara Hora Shastra — Nakshatra Phala','बुधवार गणेशलाई दूर्वा चढाउने।'),
(4,71,'बुध मूल नक्षत्रमा रहँदा बौद्धिक क्षमता र नक्षत्र शक्ति मिसिन्छ — निर्तिको नक्षत्र — जरा र विनाश। नक्षत्र स्वामी केतुसँग बुध तटस्थ हुनाले फल मध्यम रहन्छ। यो नक्षत्र धनु राशिको भागमा पर्ने हुनाले जरा खोज्ने शक्ति जस्ता फाइदा र विनाशकारी प्रवृत्ति जस्ता चुनौती दुवै देखिन्छ।',NULL,'जरा खोज्ने शक्ति, परिवर्तन, पुनर्निर्माण, बुद्धिमत्ता, वाणी कला','विनाशकारी प्रवृत्ति, आवेग, द्विधा, अति बोली','अनुसन्धान, चिकित्सा, क्रान्तिकारी काम, लेखन','उतारचढाव, पुनः सम्पत्ति, व्यापारबाट लाभ','तीव्र, कहिलेकाहीं विच्छेद, संवादमा दक्ष','बुधो मूल नक्षत्रे शुभाशुभं फलं ददाति।','Brihat Parashara Hora Shastra — Nakshatra Phala','बुधवार गणेशलाई दूर्वा चढाउने।'),
(4,72,'बुध पूर्वाषाढा नक्षत्रमा रहँदा बौद्धिक क्षमता र नक्षत्र शक्ति मिसिन्छ — अपस् नक्षत्र — अजेयता र प्रसार। नक्षत्र स्वामी शुक्र बुधको मित्रहुनाले फल सहज र शुभ हुन्छ। यो नक्षत्र धनु राशिको भागमा पर्ने हुनाले अजेय साहस जस्ता फाइदा र अति आत्मविश्वास जस्ता चुनौती दुवै देखिन्छ।',NULL,'अजेय साहस, प्रसार, विजय, बुद्धिमत्ता, वाणी कला','अति आत्मविश्वास, टकराव, द्विधा, अति बोली','सेना, नीति, प्रसार, लेखन','विस्तारबाट लाभ, व्यापारबाट लाभ, बहुआय','बलियो आवरण, तर दमन, संवादमा दक्ष','बुधो पूर्वाषाढा नक्षत्रे शुभाशुभं फलं ददाति।','Brihat Parashara Hora Shastra — Nakshatra Phala','बुधवार गणेशलाई दूर्वा चढाउने।'),
(4,73,'बुध उत्तराषाढा नक्षत्रमा रहँदा बौद्धिक क्षमता र नक्षत्र शक्ति मिसिन्छ — विश्वदेवको नक्षत्र — अन्तिम विजय। नक्षत्र स्वामी सूर्यसँग बुध तटस्थ हुनाले फल मध्यम रहन्छ। यो नक्षत्र धनु राशिको भागमा पर्ने हुनाले दिगो विजय जस्ता फाइदा र ढिलो फल जस्ता चुनौती दुवै देखिन्छ।',NULL,'दिगो विजय, सम्मान, धैर्यको फल, बुद्धिमत्ता, वाणी कला','ढिलो फल, अन्तिम समयमा दबाब, द्विधा, अति बोली','प्रशासन, दीर्घ परियोजना, लेखन, व्यापार','दिगो र स्थिर सम्पत्ति, व्यापारबाट लाभ, बहुआय','दीर्घकालीन, स्थिर, संवादमा दक्ष','बुधो उत्तराषाढा नक्षत्रे शुभाशुभं फलं ददाति।','Brihat Parashara Hora Shastra — Nakshatra Phala','बुधवार गणेशलाई दूर्वा चढाउने।'),
(4,74,'बुध श्रवण नक्षत्रमा रहँदा बौद्धिक क्षमता र नक्षत्र शक्ति मिसिन्छ — विष्णुको नक्षत्र — सुन्ने र सिक्ने। नक्षत्र स्वामी चन्द्र बुधको मित्रहुनाले फल सहज र शुभ हुन्छ। यो नक्षत्र मकर राशिको भागमा पर्ने हुनाले ज्ञान जस्ता फाइदा र अति सुन्ने जस्ता चुनौती दुवै देखिन्छ।',NULL,'ज्ञान, श्रवण कला, सम्मान, बुद्धिमत्ता, वाणी कला','अति सुन्ने, आलोचनामा संवेदनशील, द्विधा, अति बोली','शिक्षण, मीडिया, परामर्श, लेखन','ज्ञानबाट आय, व्यापारबाट लाभ, बहुआय','कुरा सुन्ने सम्बन्ध, संवादमा दक्ष, तर भावना कम','बुधो श्रवण नक्षत्रे शुभाशुभं फलं ददाति।','Brihat Parashara Hora Shastra — Nakshatra Phala','बुधवार गणेशलाई दूर्वा चढाउने।'),
(4,75,'बुध धनिष्ठा नक्षत्रमा रहँदा बौद्धिक क्षमता र नक्षत्र शक्ति मिसिन्छ — वसुको नक्षत्र — धन र समूह। नक्षत्र स्वामी मङ्गल बुधको शत्रु हुनाले चुनौती रहन्छ। यो नक्षत्र मकर राशिको भागमा पर्ने हुनाले धन संचय जस्ता फाइदा र समूहमा द्वन्द्व जस्ता चुनौती दुवै देखिन्छ।',NULL,'धन संचय, समूह नेतृत्व, कीर्ति, बुद्धिमत्ता, वाणी कला','समूहमा द्वन्द्व, अहंकार, द्विधा, अति बोली','व्यवस्थापन, समूह कार्य, संगीत, लेखन','समूह र धनबाट लाभ, व्यापारबाट लाभ, बहुआय','सामूहिक कार्यमा मिलन, संवादमा दक्ष, तर भावना कम','बुधो धनिष्ठा नक्षत्रे शुभाशुभं फलं ददाति।','Brihat Parashara Hora Shastra — Nakshatra Phala','बुधवार गणेशलाई दूर्वा चढाउने।'),
(4,76,'बुध शतभिषा नक्षत्रमा रहँदा बौद्धिक क्षमता र नक्षत्र शक्ति मिसिन्छ — वरुणको नक्षत्र — औषधि र रहस्य। नक्षत्र स्वामी राहु बुधको मित्रहुनाले फल सहज र शुभ हुन्छ। यो नक्षत्र कुम्भ राशिको भागमा पर्ने हुनाले उपचार शक्ति जस्ता फाइदा र एकान्तवाद जस्ता चुनौती दुवै देखिन्छ।',NULL,'उपचार शक्ति, गूढ विज्ञान, एकान्त साधना, बुद्धिमत्ता, वाणी कला','एकान्तवाद, भ्रम, अनिद्रा, द्विधा','चिकित्सा, विज्ञान, ज्योतिष, लेखन','अनियमित, गोप्य स्रोत, व्यापारबाट लाभ','भावनात्मक दूरी, संवादमा दक्ष, तर भावना कम','बुधो शतभिषा नक्षत्रे शुभाशुभं फलं ददाति।','Brihat Parashara Hora Shastra — Nakshatra Phala','बुधवार गणेशलाई दूर्वा चढाउने।'),
(4,77,'बुध पूर्व भाद्रपदा नक्षत्रमा रहँदा बौद्धिक क्षमता र नक्षत्र शक्ति मिसिन्छ — अज एकपदको नक्षत्र — तीव्र आदर्श। नक्षत्र स्वामी गुरु बुधको शत्रु हुनाले चुनौती रहन्छ। यो नक्षत्र कुम्भ राशिको भागमा पर्ने हुनाले दृढ आदर्श जस्ता फाइदा र तीव्रता जस्ता चुनौती दुवै देखिन्छ।',NULL,'दृढ आदर्श, त्याग, गहिरो चिन्तन, बुद्धिमत्ता, वाणी कला','तीव्रता, अन्यमाथि दबाब, द्विधा, अति बोली','आध्यात्मिक कार्य, अनुसन्धान, लेखन, व्यापार','आदर्शका लागि त्याग, व्यापारबाट लाभ, बहुआय','भावनात्मक तीव्रता, संवादमा दक्ष, तर भावना कम','बुधो पूर्व भाद्रपदा नक्षत्रे शुभाशुभं फलं ददाति।','Brihat Parashara Hora Shastra — Nakshatra Phala','बुधवार गणेशलाई दूर्वा चढाउने।'),
(4,78,'बुध उत्तर भाद्रपदा नक्षत्रमा रहँदा बौद्धिक क्षमता र नक्षत्र शक्ति मिसिन्छ — अहिर्बुध्न्यको नक्षत्र — गहिरो ज्ञान। नक्षत्र स्वामी शनि बुधको मित्रहुनाले फल सहज र शुभ हुन्छ। यो नक्षत्र मीन राशिको भागमा पर्ने हुनाले धैर्य जस्ता फाइदा र गम्भीरतामा अति जस्ता चुनौती दुवै देखिन्छ।',NULL,'धैर्य, गहिरो ज्ञान, दीर्घ आयु, बुद्धिमत्ता, वाणी कला','गम्भीरतामा अति, मौनता, द्विधा, अति बोली','विद्या, अनुसन्धान, परामर्श, लेखन','दीर्घकालीन बचत, व्यापारबाट लाभ, बहुआय','गम्भीर र दिगो सम्बन्ध, संवादमा दक्ष, तर भावना कम','बुधो उत्तर भाद्रपदा नक्षत्रे शुभाशुभं फलं ददाति।','Brihat Parashara Hora Shastra — Nakshatra Phala','बुधवार गणेशलाई दूर्वा चढाउने।'),
(4,79,'बुध रेवती नक्षत्रमा रहँदा बौद्धिक क्षमता र नक्षत्र शक्ति मिसिन्छ — पुषणको नक्षत्र — पूर्णता र पोषण। नक्षत्र स्वामी स्वयं बुध भएकाले ग्रहको प्रभाव प्रबल हुन्छ। यो नक्षत्र मीन राशिको भागमा पर्ने हुनाले पूर्णता जस्ता फाइदा र अन्त्यमा ढिलाइ जस्ता चुनौती दुवै देखिन्छ।',NULL,'पूर्णता, सुरक्षित यात्रा, पोषण, बुद्धिमत्ता, वाणी कला','अन्त्यमा ढिलाइ, अति संरक्षण, द्विधा, अति बोली','यात्रा, सेवा, परिवहन, लेखन','सुरक्षित, तर सानो, व्यापारबाट लाभ','पोषक सम्बन्ध, ममता, संवादमा दक्ष','बुधो रेवती नक्षत्रे शुभाशुभं फलं ददाति।','Brihat Parashara Hora Shastra — Nakshatra Phala','बुधवार गणेशलाई दूर्वा चढाउने।'),
(5,53,'गुरु अश्विनी नक्षत्रमा रहँदा ज्ञान गुण र नक्षत्र शक्ति मिसिन्छ — चिकित्सा र गतिको नक्षत्र। नक्षत्र स्वामी केतु गुरुको मित्रहुनाले फल सहज र शुभ हुन्छ। यो नक्षत्र मेष राशिको भागमा पर्ने हुनाले द्रुत उपचार शक्ति जस्ता फाइदा र जल्दबाजी जस्ता चुनौती दुवै देखिन्छ।',NULL,'द्रुत उपचार शक्ति, साहस, नयाँ सुरुवात, ज्ञान, भाग्य','जल्दबाजी, अधुरो काम, अति उदारता, अति आशावाद','चिकित्सा, खेलकुद, अनुसन्धान, शिक्षण','नयाँ स्रोतबाट छिटो लाभ, भाग्यबाट लाभ','स्नेहमा तीव्रता, छिटो नजिक, ज्ञानी सल्लाहकार','गुरुः अश्विनी नक्षत्रे शुभाशुभं फलं ददाति।','Brihat Parashara Hora Shastra — Nakshatra Phala','गुरुवार विष्णु मन्त्र जप गर्ने।'),
(5,54,'गुरु भरणी नक्षत्रमा रहँदा ज्ञान गुण र नक्षत्र शक्ति मिसिन्छ — यमको नक्षत्र — भार बोक्ने र परिवर्तन। नक्षत्र स्वामी शुक्रसँग गुरु तटस्थ हुनाले फल मध्यम रहन्छ। यो नक्षत्र मेष राशिको भागमा पर्ने हुनाले सहनशीलता जस्ता फाइदा र दमन जस्ता चुनौती दुवै देखिन्छ।',NULL,'सहनशीलता, जिम्मेवारी, परिवर्तन साहस, ज्ञान, भाग्य','दमन, अति बोझ, अति उदारता, अति आशावाद','प्रशासन, सेवा, न्याय, शिक्षण','परिश्रमबाट स्थिर धन, भाग्यबाट लाभ','वफादारी, तर दबाब, ज्ञानी सल्लाहकार','गुरुः भरणी नक्षत्रे शुभाशुभं फलं ददाति।','Brihat Parashara Hora Shastra — Nakshatra Phala','गुरुवार विष्णु मन्त्र जप गर्ने।'),
(5,55,'गुरु कृत्तिका नक्षत्रमा रहँदा ज्ञान गुण र नक्षत्र शक्ति मिसिन्छ — अग्निको नक्षत्र — शुद्धि र काट्ने शक्ति। नक्षत्र स्वामी सूर्य गुरुको मित्रहुनाले फल सहज र शुभ हुन्छ। यो नक्षत्र मेष राशिको भागमा पर्ने हुनाले तीक्ष्ण बुद्धि जस्ता फाइदा र कटुवाणी जस्ता चुनौती दुवै देखिन्छ।',NULL,'तीक्ष्ण बुद्धि, शुद्धता, नेतृत्व, ज्ञान, भाग्य','कटुवाणी, जल्दी निर्णय, अति उदारता, अति आशावाद','शिक्षण, चिकित्सा, अग्निसँग सम्बन्धित काम, धर्म','स्वाभिमानबाट आय, भाग्यबाट लाभ','आदर चाहने, स्पष्टवादी, ज्ञानी सल्लाहकार','गुरुः कृत्तिका नक्षत्रे शुभाशुभं फलं ददाति।','Brihat Parashara Hora Shastra — Nakshatra Phala','गुरुवार विष्णु मन्त्र जप गर्ने।'),
(5,56,'गुरु रोहिणी नक्षत्रमा रहँदा ज्ञान गुण र नक्षत्र शक्ति मिसिन्छ — ब्रह्माको नक्षत्र — वृद्धि र सौन्दर्य। नक्षत्र स्वामी चन्द्रसँग गुरु तटस्थ हुनाले फल मध्यम रहन्छ। यो नक्षत्र वृषभ राशिको भागमा पर्ने हुनाले सृजनात्मकता जस्ता फाइदा र मोह जस्ता चुनौती दुवै देखिन्छ।',NULL,'सृजनात्मकता, सम्पत्ति वृद्धि, सौन्दर्य, ज्ञान, भाग्य','मोह, अति आसक्ति, अति उदारता, अति आशावाद','कला, कृषि, व्यवस्थापन, शिक्षण','सम्पत्ति र कृषिबाट लाभ, भाग्यबाट लाभ','गहिरो स्नेह, सुन्दर सम्बन्ध, ज्ञानी सल्लाहकार','गुरुः रोहिणी नक्षत्रे शुभाशुभं फलं ददाति।','Brihat Parashara Hora Shastra — Nakshatra Phala','गुरुवार विष्णु मन्त्र जप गर्ने।'),
(5,57,'गुरु मृगशिरा नक्षत्रमा रहँदा ज्ञान गुण र नक्षत्र शक्ति मिसिन्छ — सोमको नक्षत्र — खोज र अन्वेषण। नक्षत्र स्वामी मङ्गल गुरुको मित्रहुनाले फल सहज र शुभ हुन्छ। यो नक्षत्र वृषभ राशिको भागमा पर्ने हुनाले अन्वेषण जस्ता फाइदा र अस्थिर ध्यान जस्ता चुनौती दुवै देखिन्छ।',NULL,'अन्वेषण, जिज्ञासा, रचनात्मकता, ज्ञान, भाग्य','अस्थिर ध्यान, भटकन, अति उदारता, अति आशावाद','अनुसन्धान, यात्रा, डिजाइन, शिक्षण','खोजबाट लाभ, तर ढिलाइ, भाग्यबाट लाभ','स्नेहमा खोज, अस्थिरता, ज्ञानी सल्लाहकार','गुरुः मृगशिरा नक्षत्रे शुभाशुभं फलं ददाति।','Brihat Parashara Hora Shastra — Nakshatra Phala','गुरुवार विष्णु मन्त्र जप गर्ने।'),
(5,58,'गुरु आर्द्रा नक्षत्रमा रहँदा ज्ञान गुण र नक्षत्र शक्ति मिसिन्छ — रुद्रको नक्षत्र — विनाश र पुनर्जन्म। नक्षत्र स्वामी मङ्गल गुरुको मित्रहुनाले फल सहज र शुभ हुन्छ। यो नक्षत्र मिथुन राशिको भागमा पर्ने हुनाले संकटमा टिकाउपन जस्ता फाइदा र आवेग जस्ता चुनौती दुवै देखिन्छ।',NULL,'संकटमा टिकाउपन, तीक्ष्ण बुद्धि, परिवर्तन, ज्ञान, भाग्य','आवेग, विवाद, तनाव, अति उदारता','अनुसन्धान, चिकित्सा, सुरक्षा, शिक्षण','उतारचढाव, जोखिमबाट लाभ, भाग्यबाट लाभ','तीव्र भावना, कहिलेकाहीं झगडा, ज्ञानी सल्लाहकार','गुरुः आर्द्रा नक्षत्रे शुभाशुभं फलं ददाति।','Brihat Parashara Hora Shastra — Nakshatra Phala','गुरुवार विष्णु मन्त्र जप गर्ने।'),
(5,59,'गुरु पुनर्वसु नक्षत्रमा रहँदा ज्ञान गुण र नक्षत्र शक्ति मिसिन्छ — आदितिको नक्षत्र — फिर्ता र नवीनीकरण। नक्षत्र स्वामी स्वयं गुरु भएकाले ग्रहको प्रभाव प्रबल हुन्छ। यो नक्षत्र मिथुन राशिको भागमा पर्ने हुनाले पुनर्स्थापना जस्ता फाइदा र ढिलाइ जस्ता चुनौती दुवै देखिन्छ।',NULL,'पुनर्स्थापना, भाग्य, सुरक्षा, ज्ञान, धर्म','ढिलाइ, पुरानो कुरामा फर्कने, अति उदारता, अति आशावाद','शिक्षण, यात्रा, सेवा, धर्म','पुनः अवसरबाट लाभ, भाग्यबाट लाभ','फेरि मिलाप, करुणा, ज्ञानी सल्लाहकार','गुरुः पुनर्वसु नक्षत्रे शुभाशुभं फलं ददाति।','Brihat Parashara Hora Shastra — Nakshatra Phala','गुरुवार विष्णु मन्त्र जप गर्ने।'),
(5,60,'गुरु पुष्य नक्षत्रमा रहँदा ज्ञान गुण र नक्षत्र शक्ति मिसिन्छ — बृहस्पतिको नक्षत्र — पोषण र शुभता। नक्षत्र स्वामी शनिसँग गुरु तटस्थ हुनाले फल मध्यम रहन्छ। यो नक्षत्र कर्क राशिको भागमा पर्ने हुनाले पोषण जस्ता फाइदा र अति निर्भरता जस्ता चुनौती दुवै देखिन्छ।',NULL,'पोषण, धर्म, सम्मान, शुभ आरम्भ, ज्ञान','अति निर्भरता, दायित्व बढ्ने, अति उदारता, अति आशावाद','शिक्षण, बैंकिङ, सेवा, कृषि','स्थिर र शुभ आय, भाग्यबाट लाभ','स्नेहपूर्ण, परिवारमुखी, ज्ञानी सल्लाहकार','गुरुः पुष्य नक्षत्रे शुभाशुभं फलं ददाति।','Brihat Parashara Hora Shastra — Nakshatra Phala','गुरुवार विष्णु मन्त्र जप गर्ने।'),
(5,61,'गुरु अश्लेषा नक्षत्रमा रहँदा ज्ञान गुण र नक्षत्र शक्ति मिसिन्छ — नागको नक्षत्र — भ्रमण र रहस्य। नक्षत्र स्वामी बुधसँग गुरु तटस्थ हुनाले फल मध्यम रहन्छ। यो नक्षत्र कर्क राशिको भागमा पर्ने हुनाले अन्तर्दृष्टि जस्ता फाइदा र षड्यन्त्र जस्ता चुनौती दुवै देखिन्छ।',NULL,'अन्तर्दृष्टि, जादुई आकर्षण, गूढ ज्ञान, ज्ञान, भाग्य','षड्यन्त्र, भ्रम, अति गोपन, अति उदारता','अनुसन्धान, चिकित्सा, रहस्य विषय, शिक्षण','गोप्य स्रोतबाट लाभ, भाग्यबाट लाभ','गहिरो आकर्षण, शंका, ज्ञानी सल्लाहकार','गुरुः अश्लेषा नक्षत्रे शुभाशुभं फलं ददाति।','Brihat Parashara Hora Shastra — Nakshatra Phala','गुरुवार विष्णु मन्त्र जप गर्ने।'),
(5,62,'गुरु मघा नक्षत्रमा रहँदा ज्ञान गुण र नक्षत्र शक्ति मिसिन्छ — पितृको नक्षत्र — राज्य र पूर्वज। नक्षत्र स्वामी केतु गुरुको मित्रहुनाले फल सहज र शुभ हुन्छ। यो नक्षत्र सिंह राशिको भागमा पर्ने हुनाले पूर्वजको आशीर्वाद जस्ता फाइदा र अहंकार जस्ता चुनौती दुवै देखिन्छ।',NULL,'पूर्वजको आशीर्वाद, नेतृत्व, प्रतिष्ठा, ज्ञान, भाग्य','अहंकार, परम्परामा जिद, अति उदारता, अति आशावाद','राजनीति, प्रशासन, पूर्वजसँग सम्बन्धित काम, शिक्षण','पारिवारिक सम्पत्ति, भाग्यबाट लाभ','परिवार र सम्मानमा आधारित, ज्ञानी सल्लाहकार, उदार','गुरुः मघा नक्षत्रे शुभाशुभं फलं ददाति।','Brihat Parashara Hora Shastra — Nakshatra Phala','गुरुवार विष्णु मन्त्र जप गर्ने।'),
(5,63,'गुरु पूर्व फल्गुनी नक्षत्रमा रहँदा ज्ञान गुण र नक्षत्र शक्ति मिसिन्छ — भगको नक्षत्र — सुख र सृजना। नक्षत्र स्वामी शुक्रसँग गुरु तटस्थ हुनाले फल मध्यम रहन्छ। यो नक्षत्र सिंह राशिको भागमा पर्ने हुनाले कलात्मक सुख जस्ता फाइदा र अति सुख जस्ता चुनौती दुवै देखिन्छ।',NULL,'कलात्मक सुख, रोमान्स, वैभव, ज्ञान, भाग्य','अति सुख, आलस्य, अति उदारता, अति आशावाद','कला, मनोरञ्जन, सौन्दर्य, शिक्षण','सुख साधनबाट लाभ, भाग्यबाट लाभ','प्रेमपूर्ण सम्बन्ध, आकर्षण, ज्ञानी सल्लाहकार','गुरुः पूर्व फल्गुनी नक्षत्रे शुभाशुभं फलं ददाति।','Brihat Parashara Hora Shastra — Nakshatra Phala','गुरुवार विष्णु मन्त्र जप गर्ने।'),
(5,64,'गुरु उत्तरा फल्गुनी नक्षत्रमा रहँदा ज्ञान गुण र नक्षत्र शक्ति मिसिन्छ — आर्यमाको नक्षत्र — सम्झौता र संरक्षण। नक्षत्र स्वामी सूर्य गुरुको मित्रहुनाले फल सहज र शुभ हुन्छ। यो नक्षत्र सिंह राशिको भागमा पर्ने हुनाले साझेदारी जस्ता फाइदा र बाध्यता जस्ता चुनौती दुवै देखिन्छ।',NULL,'साझेदारी, संरक्षण, विश्वास, ज्ञान, भाग्य','बाध्यता, अन्यमाथि निर्भरता, अति उदारता, अति आशावाद','कानुन, साझेदारी, संस्था, शिक्षण','साझेदारीबाट लाभ, भाग्यबाट लाभ','विश्वासयोग्य दीर्घ सम्बन्ध, ज्ञानी सल्लाहकार, उदार','गुरुः उत्तरा फल्गुनी नक्षत्रे शुभाशुभं फलं ददाति।','Brihat Parashara Hora Shastra — Nakshatra Phala','गुरुवार विष्णु मन्त्र जप गर्ने।'),
(5,65,'गुरु हस्त नक्षत्रमा रहँदा ज्ञान गुण र नक्षत्र शक्ति मिसिन्छ — सविताको नक्षत्र — हस्तकला र कौशल। नक्षत्र स्वामी चन्द्रसँग गुरु तटस्थ हुनाले फल मध्यम रहन्छ। यो नक्षत्र कन्या राशिको भागमा पर्ने हुनाले हस्तकला जस्ता फाइदा र चञ्चल हात जस्ता चुनौती दुवै देखिन्छ।',NULL,'हस्तकला, दक्षता, शीघ्र सिक्ने, ज्ञान, भाग्य','चञ्चल हात, अधुरो काम, अति उदारता, अति आशावाद','हस्तकला, चिकित्सा, डिजाइन, शिक्षण','सीपबाट आय, भाग्यबाट लाभ','सेवामा आधारित स्नेह, ज्ञानी सल्लाहकार, उदार','गुरुः हस्त नक्षत्रे शुभाशुभं फलं ददाति।','Brihat Parashara Hora Shastra — Nakshatra Phala','गुरुवार विष्णु मन्त्र जप गर्ने।'),
(5,66,'गुरु चित्रा नक्षत्रमा रहँदा ज्ञान गुण र नक्षत्र शक्ति मिसिन्छ — विश्वकर्माको नक्षत्र — निर्माण र सजावट। नक्षत्र स्वामी मङ्गल गुरुको मित्रहुनाले फल सहज र शुभ हुन्छ। यो नक्षत्र कन्या राशिको भागमा पर्ने हुनाले रचनात्मकता जस्ता फाइदा र दम्भ जस्ता चुनौती दुवै देखिन्छ।',NULL,'रचनात्मकता, सुन्दरता, प्रतिष्ठा, ज्ञान, भाग्य','दम्भ, बाह्य सजावटमा ध्यान, अति उदारता, अति आशावाद','वास्तुकला, डिजाइन, कला, शिक्षण','कलात्मक कामबाट लाभ, भाग्यबाट लाभ','आकर्षण, तर गम्भीरता कम, ज्ञानी सल्लाहकार','गुरुः चित्रा नक्षत्रे शुभाशुभं फलं ददाति।','Brihat Parashara Hora Shastra — Nakshatra Phala','गुरुवार विष्णु मन्त्र जप गर्ने।'),
(5,67,'गुरु स्वाति नक्षत्रमा रहँदा ज्ञान गुण र नक्षत्र शक्ति मिसिन्छ — वायुको नक्षत्र — स्वतन्त्रता र व्यापार। नक्षत्र स्वामी राहु गुरुको शत्रु हुनाले चुनौती रहन्छ। यो नक्षत्र तुला राशिको भागमा पर्ने हुनाले स्वतन्त्रता जस्ता फाइदा र भटकन जस्ता चुनौती दुवै देखिन्छ।',NULL,'स्वतन्त्रता, व्यापारिक बुद्धि, सहनशीलता, ज्ञान, भाग्य','भटकन, अस्थिरता, अति उदारता, अति आशावाद','व्यापार, नीति, प्रविधि, शिक्षण','व्यापारबाट चल आय, भाग्यबाट लाभ','स्वतन्त्रता चाहने सम्बन्ध, ज्ञानी सल्लाहकार, उदार','गुरुः स्वाति नक्षत्रे शुभाशुभं फलं ददाति।','Brihat Parashara Hora Shastra — Nakshatra Phala','गुरुवार विष्णु मन्त्र जप गर्ने।'),
(5,68,'गुरु विशाखा नक्षत्रमा रहँदा ज्ञान गुण र नक्षत्र शक्ति मिसिन्छ — इन्द्राग्निको नक्षत्र — लक्ष्य र उपलब्धि। नक्षत्र स्वामी स्वयं गुरु भएकाले ग्रहको प्रभाव प्रबल हुन्छ। यो नक्षत्र तुला राशिको भागमा पर्ने हुनाले लक्ष्य निश्चय जस्ता फाइदा र धैर्य कम जस्ता चुनौती दुवै देखिन्छ।',NULL,'लक्ष्य निश्चय, उपलब्धि, नेतृत्व, ज्ञान, भाग्य','धैर्य कम, अति महत्वाकांक्षा, अति उदारता, अति आशावाद','व्यवस्थापन, इन्जिनियरिङ, नेतृत्व, शिक्षण','लक्ष्य पूर्तिबाट धन, भाग्यबाट लाभ','लक्ष्यमुखी साझेदारी, ज्ञानी सल्लाहकार, उदार','गुरुः विशाखा नक्षत्रे शुभाशुभं फलं ददाति।','Brihat Parashara Hora Shastra — Nakshatra Phala','गुरुवार विष्णु मन्त्र जप गर्ने।'),
(5,69,'गुरु अनुराधा नक्षत्रमा रहँदा ज्ञान गुण र नक्षत्र शक्ति मिसिन्छ — मित्रको नक्षत्र — मित्रता र भक्ति। नक्षत्र स्वामी शनिसँग गुरु तटस्थ हुनाले फल मध्यम रहन्छ। यो नक्षत्र वृश्चिक राशिको भागमा पर्ने हुनाले मित्रता जस्ता फाइदा र मित्रमाथि अति अपेक्षा जस्ता चुनौती दुवै देखिन्छ।',NULL,'मित्रता, भक्ति, सङ्गठन क्षमता, ज्ञान, भाग्य','मित्रमाथि अति अपेक्षा, अति उदारता, अति आशावाद','सङ्गठन, सेवा, धार्मिक कार्य, शिक्षण','मित्रबाट लाभ, भाग्यबाट लाभ','गहिरो मित्रता, विश्वास, ज्ञानी सल्लाहकार','गुरुः अनुराधा नक्षत्रे शुभाशुभं फलं ददाति।','Brihat Parashara Hora Shastra — Nakshatra Phala','गुरुवार विष्णु मन्त्र जप गर्ने।'),
(5,70,'गुरु ज्येष्ठा नक्षत्रमा रहँदा ज्ञान गुण र नक्षत्र शक्ति मिसिन्छ — इन्द्रको नक्षत्र — वरिष्ठता र संरक्षण। नक्षत्र स्वामी बुधसँग गुरु तटस्थ हुनाले फल मध्यम रहन्छ। यो नक्षत्र वृश्चिक राशिको भागमा पर्ने हुनाले नेतृत्व जस्ता फाइदा र अहंकार जस्ता चुनौती दुवै देखिन्छ।',NULL,'नेतृत्व, संरक्षण, अनुभव, ज्ञान, भाग्य','अहंकार, ईर्ष्या, अति उदारता, अति आशावाद','प्रशासन, न्याय, वरिष्ठ पद, शिक्षण','स्थापित स्रोतबाट लाभ, भाग्यबाट लाभ','संरक्षक भूमिका, ज्ञानी सल्लाहकार, उदार','गुरुः ज्येष्ठा नक्षत्रे शुभाशुभं फलं ददाति।','Brihat Parashara Hora Shastra — Nakshatra Phala','गुरुवार विष्णु मन्त्र जप गर्ने।'),
(5,71,'गुरु मूल नक्षत्रमा रहँदा ज्ञान गुण र नक्षत्र शक्ति मिसिन्छ — निर्तिको नक्षत्र — जरा र विनाश। नक्षत्र स्वामी केतु गुरुको मित्रहुनाले फल सहज र शुभ हुन्छ। यो नक्षत्र धनु राशिको भागमा पर्ने हुनाले जरा खोज्ने शक्ति जस्ता फाइदा र विनाशकारी प्रवृत्ति जस्ता चुनौती दुवै देखिन्छ।',NULL,'जरा खोज्ने शक्ति, परिवर्तन, पुनर्निर्माण, ज्ञान, भाग्य','विनाशकारी प्रवृत्ति, आवेग, अति उदारता, अति आशावाद','अनुसन्धान, चिकित्सा, क्रान्तिकारी काम, शिक्षण','उतारचढाव, पुनः सम्पत्ति, भाग्यबाट लाभ','तीव्र, कहिलेकाहीं विच्छेद, ज्ञानी सल्लाहकार','गुरुः मूल नक्षत्रे शुभाशुभं फलं ददाति।','Brihat Parashara Hora Shastra — Nakshatra Phala','गुरुवार विष्णु मन्त्र जप गर्ने।'),
(5,72,'गुरु पूर्वाषाढा नक्षत्रमा रहँदा ज्ञान गुण र नक्षत्र शक्ति मिसिन्छ — अपस् नक्षत्र — अजेयता र प्रसार। नक्षत्र स्वामी शुक्रसँग गुरु तटस्थ हुनाले फल मध्यम रहन्छ। यो नक्षत्र धनु राशिको भागमा पर्ने हुनाले अजेय साहस जस्ता फाइदा र अति आत्मविश्वास जस्ता चुनौती दुवै देखिन्छ।',NULL,'अजेय साहस, प्रसार, विजय, ज्ञान, भाग्य','अति आत्मविश्वास, टकराव, अति उदारता, अति आशावाद','सेना, नीति, प्रसार, शिक्षण','विस्तारबाट लाभ, भाग्यबाट लाभ','बलियो आवरण, तर दमन, ज्ञानी सल्लाहकार','गुरुः पूर्वाषाढा नक्षत्रे शुभाशुभं फलं ददाति।','Brihat Parashara Hora Shastra — Nakshatra Phala','गुरुवार विष्णु मन्त्र जप गर्ने।'),
(5,73,'गुरु उत्तराषाढा नक्षत्रमा रहँदा ज्ञान गुण र नक्षत्र शक्ति मिसिन्छ — विश्वदेवको नक्षत्र — अन्तिम विजय। नक्षत्र स्वामी सूर्य गुरुको मित्रहुनाले फल सहज र शुभ हुन्छ। यो नक्षत्र धनु राशिको भागमा पर्ने हुनाले दिगो विजय जस्ता फाइदा र ढिलो फल जस्ता चुनौती दुवै देखिन्छ।',NULL,'दिगो विजय, सम्मान, धैर्यको फल, ज्ञान, भाग्य','ढिलो फल, अन्तिम समयमा दबाब, अति उदारता, अति आशावाद','प्रशासन, दीर्घ परियोजना, शिक्षण, धर्म','दिगो र स्थिर सम्पत्ति, भाग्यबाट लाभ','दीर्घकालीन, स्थिर, ज्ञानी सल्लाहकार','गुरुः उत्तराषाढा नक्षत्रे शुभाशुभं फलं ददाति।','Brihat Parashara Hora Shastra — Nakshatra Phala','गुरुवार विष्णु मन्त्र जप गर्ने।'),
(5,74,'गुरु श्रवण नक्षत्रमा रहँदा ज्ञान गुण र नक्षत्र शक्ति मिसिन्छ — विष्णुको नक्षत्र — सुन्ने र सिक्ने। नक्षत्र स्वामी चन्द्रसँग गुरु तटस्थ हुनाले फल मध्यम रहन्छ। यो नक्षत्र मकर राशिको भागमा पर्ने हुनाले ज्ञान जस्ता फाइदा र अति सुन्ने जस्ता चुनौती दुवै देखिन्छ।',NULL,'ज्ञान, श्रवण कला, सम्मान, भाग्य, धर्म','अति सुन्ने, आलोचनामा संवेदनशील, अति उदारता, अति आशावाद','शिक्षण, मीडिया, परामर्श, धर्म','ज्ञानबाट आय, भाग्यबाट लाभ','कुरा सुन्ने सम्बन्ध, ज्ञानी सल्लाहकार, उदार','गुरुः श्रवण नक्षत्रे शुभाशुभं फलं ददाति।','Brihat Parashara Hora Shastra — Nakshatra Phala','गुरुवार विष्णु मन्त्र जप गर्ने।'),
(5,75,'गुरु धनिष्ठा नक्षत्रमा रहँदा ज्ञान गुण र नक्षत्र शक्ति मिसिन्छ — वसुको नक्षत्र — धन र समूह। नक्षत्र स्वामी मङ्गल गुरुको मित्रहुनाले फल सहज र शुभ हुन्छ। यो नक्षत्र मकर राशिको भागमा पर्ने हुनाले धन संचय जस्ता फाइदा र समूहमा द्वन्द्व जस्ता चुनौती दुवै देखिन्छ।',NULL,'धन संचय, समूह नेतृत्व, कीर्ति, ज्ञान, भाग्य','समूहमा द्वन्द्व, अहंकार, अति उदारता, अति आशावाद','व्यवस्थापन, समूह कार्य, संगीत, शिक्षण','समूह र धनबाट लाभ, भाग्यबाट लाभ','सामूहिक कार्यमा मिलन, ज्ञानी सल्लाहकार, उदार','गुरुः धनिष्ठा नक्षत्रे शुभाशुभं फलं ददाति।','Brihat Parashara Hora Shastra — Nakshatra Phala','गुरुवार विष्णु मन्त्र जप गर्ने।'),
(5,76,'गुरु शतभिषा नक्षत्रमा रहँदा ज्ञान गुण र नक्षत्र शक्ति मिसिन्छ — वरुणको नक्षत्र — औषधि र रहस्य। नक्षत्र स्वामी राहु गुरुको शत्रु हुनाले चुनौती रहन्छ। यो नक्षत्र कुम्भ राशिको भागमा पर्ने हुनाले उपचार शक्ति जस्ता फाइदा र एकान्तवाद जस्ता चुनौती दुवै देखिन्छ।',NULL,'उपचार शक्ति, गूढ विज्ञान, एकान्त साधना, ज्ञान, भाग्य','एकान्तवाद, भ्रम, अनिद्रा, अति उदारता','चिकित्सा, विज्ञान, ज्योतिष, शिक्षण','अनियमित, गोप्य स्रोत, भाग्यबाट लाभ','भावनात्मक दूरी, ज्ञानी सल्लाहकार, उदार','गुरुः शतभिषा नक्षत्रे शुभाशुभं फलं ददाति।','Brihat Parashara Hora Shastra — Nakshatra Phala','गुरुवार विष्णु मन्त्र जप गर्ने।'),
(5,77,'गुरु पूर्व भाद्रपदा नक्षत्रमा रहँदा ज्ञान गुण र नक्षत्र शक्ति मिसिन्छ — अज एकपदको नक्षत्र — तीव्र आदर्श। नक्षत्र स्वामी स्वयं गुरु भएकाले ग्रहको प्रभाव प्रबल हुन्छ। यो नक्षत्र कुम्भ राशिको भागमा पर्ने हुनाले दृढ आदर्श जस्ता फाइदा र तीव्रता जस्ता चुनौती दुवै देखिन्छ।',NULL,'दृढ आदर्श, त्याग, गहिरो चिन्तन, ज्ञान, भाग्य','तीव्रता, अन्यमाथि दबाब, अति उदारता, अति आशावाद','आध्यात्मिक कार्य, अनुसन्धान, शिक्षण, धर्म','आदर्शका लागि त्याग, भाग्यबाट लाभ','भावनात्मक तीव्रता, ज्ञानी सल्लाहकार, उदार','गुरुः पूर्व भाद्रपदा नक्षत्रे शुभाशुभं फलं ददाति।','Brihat Parashara Hora Shastra — Nakshatra Phala','गुरुवार विष्णु मन्त्र जप गर्ने।'),
(5,78,'गुरु उत्तर भाद्रपदा नक्षत्रमा रहँदा ज्ञान गुण र नक्षत्र शक्ति मिसिन्छ — अहिर्बुध्न्यको नक्षत्र — गहिरो ज्ञान। नक्षत्र स्वामी शनिसँग गुरु तटस्थ हुनाले फल मध्यम रहन्छ। यो नक्षत्र मीन राशिको भागमा पर्ने हुनाले धैर्य जस्ता फाइदा र गम्भीरतामा अति जस्ता चुनौती दुवै देखिन्छ।',NULL,'धैर्य, गहिरो ज्ञान, दीर्घ आयु, ज्ञान, भाग्य','गम्भीरतामा अति, मौनता, अति उदारता, अति आशावाद','विद्या, अनुसन्धान, परामर्श, शिक्षण','दीर्घकालीन बचत, भाग्यबाट लाभ','गम्भीर र दिगो सम्बन्ध, ज्ञानी सल्लाहकार, उदार','गुरुः उत्तर भाद्रपदा नक्षत्रे शुभाशुभं फलं ददाति।','Brihat Parashara Hora Shastra — Nakshatra Phala','गुरुवार विष्णु मन्त्र जप गर्ने।'),
(5,79,'गुरु रेवती नक्षत्रमा रहँदा ज्ञान गुण र नक्षत्र शक्ति मिसिन्छ — पुषणको नक्षत्र — पूर्णता र पोषण। नक्षत्र स्वामी बुधसँग गुरु तटस्थ हुनाले फल मध्यम रहन्छ। यो नक्षत्र मीन राशिको भागमा पर्ने हुनाले पूर्णता जस्ता फाइदा र अन्त्यमा ढिलाइ जस्ता चुनौती दुवै देखिन्छ।',NULL,'पूर्णता, सुरक्षित यात्रा, पोषण, ज्ञान, भाग्य','अन्त्यमा ढिलाइ, अति संरक्षण, अति उदारता, अति आशावाद','यात्रा, सेवा, परिवहन, शिक्षण','सुरक्षित, तर सानो, भाग्यबाट लाभ','पोषक सम्बन्ध, ममता, ज्ञानी सल्लाहकार','गुरुः रेवती नक्षत्रे शुभाशुभं फलं ददाति।','Brihat Parashara Hora Shastra — Nakshatra Phala','गुरुवार विष्णु मन्त्र जप गर्ने।'),
(6,53,'शुक्र अश्विनी नक्षत्रमा रहँदा कला र सौन्दर्य र नक्षत्र शक्ति मिसिन्छ — चिकित्सा र गतिको नक्षत्र। नक्षत्र स्वामी केतु शुक्रको शत्रु हुनाले चुनौती रहन्छ। यो नक्षत्र मेष राशिको भागमा पर्ने हुनाले द्रुत उपचार शक्ति जस्ता फाइदा र जल्दबाजी जस्ता चुनौती दुवै देखिन्छ।',NULL,'द्रुत उपचार शक्ति, साहस, नयाँ सुरुवात, सौन्दर्य, कला','जल्दबाजी, अधुरो काम, सान्द्रता, अति भोग','चिकित्सा, खेलकुद, अनुसन्धान, कला','नयाँ स्रोतबाट छिटो लाभ, भौतिक सुख र धन','स्नेहमा तीव्रता, छिटो नजिक, प्रेमपूर्ण सम्बन्ध','शुक्रः अश्विनी नक्षत्रे शुभाशुभं फलं ददाति।','Brihat Parashara Hora Shastra — Nakshatra Phala','शुक्रबार लक्ष्मी मन्त्र जप गर्ने।'),
(6,54,'शुक्र भरणी नक्षत्रमा रहँदा कला र सौन्दर्य र नक्षत्र शक्ति मिसिन्छ — यमको नक्षत्र — भार बोक्ने र परिवर्तन। नक्षत्र स्वामी स्वयं शुक्र भएकाले ग्रहको प्रभाव प्रबल हुन्छ। यो नक्षत्र मेष राशिको भागमा पर्ने हुनाले सहनशीलता जस्ता फाइदा र दमन जस्ता चुनौती दुवै देखिन्छ।',NULL,'सहनशीलता, जिम्मेवारी, परिवर्तन साहस, सौन्दर्य, कला','दमन, अति बोझ, सान्द्रता, अति भोग','प्रशासन, सेवा, न्याय, कला','परिश्रमबाट स्थिर धन, भौतिक सुख र धन','वफादारी, तर दबाब, प्रेमपूर्ण सम्बन्ध','शुक्रः भरणी नक्षत्रे शुभाशुभं फलं ददाति।','Brihat Parashara Hora Shastra — Nakshatra Phala','शुक्रबार लक्ष्मी मन्त्र जप गर्ने।'),
(6,55,'शुक्र कृत्तिका नक्षत्रमा रहँदा कला र सौन्दर्य र नक्षत्र शक्ति मिसिन्छ — अग्निको नक्षत्र — शुद्धि र काट्ने शक्ति। नक्षत्र स्वामी सूर्य शुक्रको शत्रु हुनाले चुनौती रहन्छ। यो नक्षत्र मेष राशिको भागमा पर्ने हुनाले तीक्ष्ण बुद्धि जस्ता फाइदा र कटुवाणी जस्ता चुनौती दुवै देखिन्छ।',NULL,'तीक्ष्ण बुद्धि, शुद्धता, नेतृत्व, सौन्दर्य, कला','कटुवाणी, जल्दी निर्णय, सान्द्रता, अति भोग','शिक्षण, चिकित्सा, अग्निसँग सम्बन्धित काम, कला','स्वाभिमानबाट आय, भौतिक सुख र धन','आदर चाहने, स्पष्टवादी, प्रेमपूर्ण सम्बन्ध','शुक्रः कृत्तिका नक्षत्रे शुभाशुभं फलं ददाति।','Brihat Parashara Hora Shastra — Nakshatra Phala','शुक्रबार लक्ष्मी मन्त्र जप गर्ने।'),
(6,56,'शुक्र रोहिणी नक्षत्रमा रहँदा कला र सौन्दर्य र नक्षत्र शक्ति मिसिन्छ — ब्रह्माको नक्षत्र — वृद्धि र सौन्दर्य। नक्षत्र स्वामी चन्द्रसँग शुक्र तटस्थ हुनाले फल मध्यम रहन्छ। यो नक्षत्र वृषभ राशिको भागमा पर्ने हुनाले सृजनात्मकता जस्ता फाइदा र मोह जस्ता चुनौती दुवै देखिन्छ।',NULL,'सृजनात्मकता, सम्पत्ति वृद्धि, सौन्दर्य, कला, वैवाहिक सुख','मोह, अति आसक्ति, सान्द्रता, अति भोग','कला, कृषि, व्यवस्थापन, डिजाइन','सम्पत्ति र कृषिबाट लाभ, भौतिक सुख र धन','गहिरो स्नेह, सुन्दर सम्बन्ध, प्रेमपूर्ण सम्बन्ध','शुक्रः रोहिणी नक्षत्रे शुभाशुभं फलं ददाति।','Brihat Parashara Hora Shastra — Nakshatra Phala','शुक्रबार लक्ष्मी मन्त्र जप गर्ने।'),
(6,57,'शुक्र मृगशिरा नक्षत्रमा रहँदा कला र सौन्दर्य र नक्षत्र शक्ति मिसिन्छ — सोमको नक्षत्र — खोज र अन्वेषण। नक्षत्र स्वामी मङ्गल शुक्रको शत्रु हुनाले चुनौती रहन्छ। यो नक्षत्र वृषभ राशिको भागमा पर्ने हुनाले अन्वेषण जस्ता फाइदा र अस्थिर ध्यान जस्ता चुनौती दुवै देखिन्छ।',NULL,'अन्वेषण, जिज्ञासा, रचनात्मकता, सौन्दर्य, कला','अस्थिर ध्यान, भटकन, सान्द्रता, अति भोग','अनुसन्धान, यात्रा, डिजाइन, कला','खोजबाट लाभ, तर ढिलाइ, भौतिक सुख र धन','स्नेहमा खोज, अस्थिरता, प्रेमपूर्ण सम्बन्ध','शुक्रः मृगशिरा नक्षत्रे शुभाशुभं फलं ददाति।','Brihat Parashara Hora Shastra — Nakshatra Phala','शुक्रबार लक्ष्मी मन्त्र जप गर्ने।'),
(6,58,'शुक्र आर्द्रा नक्षत्रमा रहँदा कला र सौन्दर्य र नक्षत्र शक्ति मिसिन्छ — रुद्रको नक्षत्र — विनाश र पुनर्जन्म। नक्षत्र स्वामी मङ्गल शुक्रको शत्रु हुनाले चुनौती रहन्छ। यो नक्षत्र मिथुन राशिको भागमा पर्ने हुनाले संकटमा टिकाउपन जस्ता फाइदा र आवेग जस्ता चुनौती दुवै देखिन्छ।',NULL,'संकटमा टिकाउपन, तीक्ष्ण बुद्धि, परिवर्तन, सौन्दर्य, कला','आवेग, विवाद, तनाव, सान्द्रता','अनुसन्धान, चिकित्सा, सुरक्षा, कला','उतारचढाव, जोखिमबाट लाभ, भौतिक सुख र धन','तीव्र भावना, कहिलेकाहीं झगडा, प्रेमपूर्ण सम्बन्ध','शुक्रः आर्द्रा नक्षत्रे शुभाशुभं फलं ददाति।','Brihat Parashara Hora Shastra — Nakshatra Phala','शुक्रबार लक्ष्मी मन्त्र जप गर्ने।'),
(6,59,'शुक्र पुनर्वसु नक्षत्रमा रहँदा कला र सौन्दर्य र नक्षत्र शक्ति मिसिन्छ — आदितिको नक्षत्र — फिर्ता र नवीनीकरण। नक्षत्र स्वामी गुरु शुक्रको शत्रु हुनाले चुनौती रहन्छ। यो नक्षत्र मिथुन राशिको भागमा पर्ने हुनाले पुनर्स्थापना जस्ता फाइदा र ढिलाइ जस्ता चुनौती दुवै देखिन्छ।',NULL,'पुनर्स्थापना, भाग्य, सुरक्षा, सौन्दर्य, कला','ढिलाइ, पुरानो कुरामा फर्कने, सान्द्रता, अति भोग','शिक्षण, यात्रा, सेवा, कला','पुनः अवसरबाट लाभ, भौतिक सुख र धन','फेरि मिलाप, करुणा, प्रेमपूर्ण सम्बन्ध','शुक्रः पुनर्वसु नक्षत्रे शुभाशुभं फलं ददाति।','Brihat Parashara Hora Shastra — Nakshatra Phala','शुक्रबार लक्ष्मी मन्त्र जप गर्ने।'),
(6,60,'शुक्र पुष्य नक्षत्रमा रहँदा कला र सौन्दर्य र नक्षत्र शक्ति मिसिन्छ — बृहस्पतिको नक्षत्र — पोषण र शुभता। नक्षत्र स्वामी शनि शुक्रको मित्रहुनाले फल सहज र शुभ हुन्छ। यो नक्षत्र कर्क राशिको भागमा पर्ने हुनाले पोषण जस्ता फाइदा र अति निर्भरता जस्ता चुनौती दुवै देखिन्छ।',NULL,'पोषण, धर्म, सम्मान, शुभ आरम्भ, सौन्दर्य','अति निर्भरता, दायित्व बढ्ने, सान्द्रता, अति भोग','शिक्षण, बैंकिङ, सेवा, कृषि','स्थिर र शुभ आय, भौतिक सुख र धन','स्नेहपूर्ण, परिवारमुखी, प्रेमपूर्ण सम्बन्ध','शुक्रः पुष्य नक्षत्रे शुभाशुभं फलं ददाति।','Brihat Parashara Hora Shastra — Nakshatra Phala','शुक्रबार लक्ष्मी मन्त्र जप गर्ने।'),
